/** All translations for zizhitongjian ch.044 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑第044卷", literal: "Zizhi Tongjian, Volume 44.", idiomatic: "Zizhi Tongjian, Volume 44." },
  { zh: "【漢紀三十六】起強圉協洽，盡上章涒灘，凡十四年。", literal: "【Han Records 36】 From Qiangyu Xieqia through Shangzhang Tushan—in all, fourteen years.", idiomatic: "【Han Records 36】 From the first year of the Qiangyu cycle through the last year of the Shangzhang cycle—fourteen years in all." },
  { zh: "春，正月，南郡蠻叛；", literal: "In spring, the first month, the Nan commandery tribes rebelled;", idiomatic: "In spring, in the first month, the tribes of Nan commandery rebelled;" },
  { zh: "遣武威將軍劉尚討破之。", literal: "the General of Majestic Might Liu Shang was sent to attack and break them.", idiomatic: "the emperor sent General of Majestic Might Liu Shang to crush them." },
  { zh: "夏，五月，丁卯，大司徒蔡茂薨。", literal: "In summer, the fifth month, on the day dingmao, Grand Minister of Education Cai Mao died.", idiomatic: "In summer, in the fifth month, on dingmao day, Grand Minister of Education Cai Mao died." },
  { zh: "秋，八月，丙戌，大司空杜林薨。", literal: "In autumn, the eighth month, on the day bingxu, Grand Minister of Works Du Lin died.", idiomatic: "In autumn, in the eighth month, on bingxu day, Grand Minister of Works Du Lin died." },
  { zh: "九月，辛未，以陳留太守王況為大司徒。", literal: "In the ninth month, on the day xinwei, Chenliu Administrator Wang Kuang was made Grand Minister of Education.", idiomatic: "In the ninth month, on xinwei day, Chenliu Administrator Wang Kuang was appointed Grand Minister of Education." },
  { zh: "冬，十月，丙申，以太僕張純為大司空。", literal: "In winter, the tenth month, on the day bingshen, the Grand Steward Zhang Chun was made Grand Minister of Works.", idiomatic: "In winter, in the tenth month, on bingshen day, Grand Steward Zhang Chun was appointed Grand Minister of Works." },
  { zh: "武陵蠻精夫相單程等反，遣劉尚發兵萬餘人溯沅水入武谿擊之。", literal: "The Wuling tribes' chieftains Xiang Dancheng and others rebelled; Liu Shang was sent with more than ten thousand troops up the Yuan River into Wu Xi to strike them.", idiomatic: "The Wuling chieftains Xiang Dancheng and others rose in revolt. Liu Shang was sent with more than ten thousand men up the Yuan River into Wu Xi to attack them." },
  { zh: "尚輕敵深入，蠻乘險邀之，尚一軍悉沒。", literal: "Shang treated the enemy lightly and drove deep; the tribes used the terrain to ambush him, and Shang's whole army was destroyed.", idiomatic: "Shang despised the foe and marched too deep. The tribes ambushed him from the high ground, and his entire army was wiped out." },
  { zh: "初，匈奴單于輿弟右谷蠡王知牙師，以次當為左賢王，左賢王次即當為單于。", literal: "Earlier, the Xiongnu chanyu Yu's younger brother, the Right Guli King Zhiyashi, by order of succession ought to become Left Wise Prince, and the Left Wise Prince in turn ought to become chanyu.", idiomatic: "Earlier, the Xiongnu chanyu Yu's younger brother, Right Guli King Zhiyashi, stood next in line for the Left Wise Princedom, and the Left Wise Prince stood next for the chanyu's throne." },
  { zh: "單于欲傳其子，遂殺知牙師。", literal: "The chanyu wished to pass the throne to his own son and thereupon killed Zhiyashi.", idiomatic: "The chanyu meant to pass the throne to his son and killed Zhiyashi." },
  { zh: "烏珠留單于有子曰比，為右薁鞬日逐王，領南邊八部。", literal: "Wuzhuliu Chanyu had a son named Bi, who was Right Guli Jian Daily-chasing King and commanded the eight tribes of the southern border.", idiomatic: "Wuzhuliu Chanyu had a son, Bi, Right Guli Jian Daily-chasing King, who held the eight southern tribes." },
  { zh: "比見知牙師死，出怨言曰：「以兄弟言之，右谷蠡王次當立；", literal: "When Bi saw Zhiyashi dead, he spoke resentment aloud: \"Speaking as among brothers, the Right Guli King is next and ought to be established;\"", idiomatic: "When Bi saw Zhiyashi dead, he spoke his grievance aloud: \"By the order of brothers, the Right Guli King should be raised next;" },
  { zh: "以子言之，我前單于長子，我當立。", literal: "\"speaking as among sons, I am the former chanyu's eldest son—I ought to be established.\"", idiomatic: "\"by the order of sons, I am the late chanyu's eldest son—I should be raised.\"" },
  { zh: "」遂內懷猜懼，庭會稀闊。", literal: "\" He thereupon harbored suspicion and fear inwardly; court assemblies grew few and distant.", idiomatic: "\" From then on he nursed suspicion and dread, and came seldom to court." },
  { zh: "單于疑之，乃遣兩骨都侯監領比所部兵。", literal: "The chanyu suspected him and sent the two Gudu Marquises to oversee and command Bi's tribal troops.", idiomatic: "The chanyu mistrusted him and sent the two Gudu Marquises to oversee Bi's forces." },
  { zh: "及單于蒲奴立，比益恨望，密遣漢人郭衡奉匈奴地圖，詣西河太守求內附。", literal: "When Chanyu Punu was established, Bi's resentment grew; secretly he sent the Han man Guo Heng bearing a Xiongnu map to the Administrator of Xihe to seek inner submission.", idiomatic: "When Chanyu Punu took the throne, Bi's bitterness deepened. He secretly sent the Han subject Guo Heng with a map of Xiongnu lands to the Administrator of Xihe to ask to submit inward." },
  { zh: "兩骨都侯頗覺其意，會五月龍祠，勸單于誅比。", literal: "The two Gudu Marquises largely perceived his intent; at the May dragon sacrifice they urged the chanyu to execute Bi.", idiomatic: "The two Gudu Marquises sensed his intent. At the May dragon rites they urged the chanyu to kill Bi." },
  { zh: "比弟漸將王在單于帳下，聞之，馳以報比。", literal: "Bi's younger brother, the Jianjiang King, was at the chanyu's tent; hearing of it, he galloped to report to Bi.", idiomatic: "Bi's younger brother Jianjiang King was at the chanyu's tent. Hearing the plot, he raced to warn Bi." },
  { zh: "比遂聚八部兵四五萬人，待兩骨都侯還，欲殺之。", literal: "Bi thereupon gathered forty or fifty thousand men from the eight tribes, intending when the two Gudu Marquises returned to kill them.", idiomatic: "Bi mustered forty or fifty thousand men from the eight tribes and waited for the two Gudu Marquises to return, meaning to kill them." },
  { zh: "骨都侯且到，知其謀，亡去。", literal: "The Gudu Marquises were about to arrive, learned of the plot, and fled.", idiomatic: "The Gudu Marquises were nearly there, learned of the plot, and fled." },
  { zh: "單于遣萬騎擊之，見比眾盛，不敢進而還。", literal: "The chanyu sent ten thousand horse to strike him; seeing Bi's host was strong, they dared not advance and returned.", idiomatic: "The chanyu sent ten thousand cavalry against him, but seeing Bi's strength, they dared not press on and withdrew." },
  { zh: "是歲，鬲侯朱祜薨。", literal: "This year Marquis of Ge Zhu Hu died.", idiomatic: "That year Marquis of Ge Zhu Hu died." },
  { zh: "祜為人質直，尚儒學；", literal: "Hu was plain and upright in person and esteemed Confucian learning;", idiomatic: "Hu was plainspoken and upright, and honored Confucian learning;" },
  { zh: "為將多受降，以克定城邑為本，不存首級之功。", literal: "as a general he often accepted surrenders, taking the securing of cities and towns as his root, and did not keep count of heads for merit.", idiomatic: "as a commander he often took surrenders, measured merit by cities secured, and cared nothing for head counts." },
  { zh: "又禁制士卒不得虜掠百姓。", literal: "He also forbade the soldiers to plunder or seize the common people.", idiomatic: "He also forbade his men to loot or seize civilians." },
  { zh: "軍人樂放縱，多以此怨之。", literal: "The troops delighted in license and for this largely resented him.", idiomatic: "The troops loved their license, and for this many resented him." },
  { zh: "春，正月，乙亥，赦天下。", literal: "In spring, the first month, on the day yihai, the realm was pardoned.", idiomatic: "In spring, in the first month, on yihai day, the emperor pardoned the realm." },
  { zh: "匈奴八部大人共議立日逐王比為呼韓邪單于，款五原塞，願永為籓蔽，扦御北虜。", literal: "The great men of the Xiongnu eight tribes jointly resolved to establish Daily-chasing King Bi as Huhanye Chanyu; he came in sincerity to the Wuyuan pass and wished forever to be a frontier screen and ward off the northern foe.", idiomatic: "The elders of the eight Xiongnu tribes agreed to raise Daily-chasing King Bi as Huhanye Chanyu. He came in good faith to the Wuyuan frontier and asked to stand forever as a vassal screen against the northern enemy." },
  { zh: "事下公卿，議者皆以為：「天下初定，中國空虛，夷狄情偽難知，不可許。", literal: "The matter was sent down to the excellencies and ministers; debaters all said: \"The realm is newly settled, the central lands are empty, the tribes' truth and falsehood are hard to know—it cannot be granted.\"", idiomatic: "The matter went to the high ministers. The consensus ran: \"The realm is newly settled and the heartland still empty. Tribal sincerity is hard to read. This must not be granted.\"" },
  { zh: "」五官中郎將耿國獨以為：「宜如孝宣故事，受之。", literal: "\" The Palace Attendant Geng Guo alone held: \"One ought, as in Emperor Xiaoxuan's precedent, to accept him.\"", idiomatic: "\" Palace Attendant Geng Guo alone argued, \"We should accept him, as Emperor Xiaoxuan did.\"" },
  { zh: "令東扞鮮卑，北拒匈奴，率厲四夷，完復邊郡。", literal: "\"Let him hold the east against the Xianbei, hold the north against the Xiongnu, lead and encourage the four tribes, and restore the border commanderies to wholeness.\"", idiomatic: "\"Let him shield the east from the Xianbei, hold the north against the Xiongnu, rally the four tribes, and restore our border commanderies.\"" },
  { zh: "」帝從之。", literal: "\" The emperor followed this.", idiomatic: "\" The emperor agreed." },
  { zh: "秋，七月，武陵蠻寇臨沅。", literal: "In autumn, the seventh month, the Wuling tribes raided Linyuan.", idiomatic: "In autumn, in the seventh month, the Wuling tribes attacked Linyuan." },
  { zh: "遣謁者李嵩、中山太守馬成討之，不克。", literal: "The Herald Li Song and Zhongshan Administrator Ma Cheng were sent to attack them and did not overcome.", idiomatic: "The emperor sent Herald Li Song and Zhongshan Administrator Ma Cheng against them, but they could not prevail." },
  { zh: "馬援請行，帝愍其老，未許，援曰：「臣尚能被甲上馬。", literal: "Ma Yuan asked to go; the emperor pitied his age and did not consent; Yuan said: \"Your servant can still don armor and mount a horse.\"", idiomatic: "Ma Yuan asked to lead the campaign. The emperor pitied his age and refused. Yuan said, \"Your servant can still buckle on armor and mount a horse.\"" },
  { zh: "」帝令試之。", literal: "\" The emperor ordered him tested.", idiomatic: "\" The emperor bade him prove it." },
  { zh: "援據鞍顧眄，以示可用，帝笑曰：「矍鑠哉是翁！", literal: "Yuan gripped the saddle and looked about to show himself fit; the emperor laughed and said: \"Spry indeed, this old man!\"", idiomatic: "Yuan gripped the saddle and glanced about to show he was fit. The emperor laughed. \"Spry indeed, this old man!\"" },
  { zh: "」遂遣授率中郎將馬武、耿舒等將四萬餘人，征五溪。", literal: "\" He thereupon sent him to lead Palace Gentlemen Ma Wu, Geng Shu, and others with more than forty thousand men to campaign in Wuxi.", idiomatic: "\" He sent Yuan at the head of Palace Gentlemen Ma Wu, Geng Shu, and more than forty thousand men against Wuxi." },
  { zh: "援謂友人杜愔曰：「吾受厚恩，年迫日索，常恐不得死國事。", literal: "Yuan said to his friend Du Yin: \"I have received deep grace; my years press and the days shorten—I constantly fear I shall not die in the state's service.\"", idiomatic: "Yuan told his friend Du Yin, \"I owe the throne a great debt. My years press on and the days run short. I have long feared I would not die in the state's service.\"" },
  { zh: "今獲所願，甘心瞑目，但畏長者家兒或在左右，或與從事，殊難得調，介介獨惡是耳！", literal: "\"Now I have gained my wish and would close my eyes content—only I fear some elder's household son may be at my side or share the command; he will be especially hard to harmonize with, and that alone I greatly dread!\"", idiomatic: "\"Now I have my wish and could die content. Only I fear some young lord of a great house may ride at my side or share my command—such men are hard to manage, and that alone I dread!\"" },
  { zh: "冬，十月，匈奴日逐王比自立為南單于，遣使詣闕奉籓稱臣。", literal: "In winter, the tenth month, the Xiongnu Daily-chasing King Bi established himself as Southern Chanyu and sent envoys to the court to offer vassal submission and call himself subject.", idiomatic: "In winter, in the tenth month, the Xiongnu Daily-chasing King Bi declared himself Southern Chanyu and sent envoys to court with tribute, calling himself a vassal." },
  { zh: "上以問朗陵侯臧宮。", literal: "The emperor questioned Marquis of Langling Zang Gong.", idiomatic: "The emperor asked Marquis of Langling Zang Gong." },
  { zh: "宮曰：「匈奴饑疫分爭，臣願得五千騎以立功。", literal: "Gong said: \"The Xiongnu suffer hunger and plague and are sundered in strife—your servant would take five thousand horse to achieve merit.\"", idiomatic: "Gong said, \"The Xiongnu are starving, plague-struck, and torn by strife. Give your servant five thousand horse and I will win merit.\"" },
  { zh: "」帝笑曰：「常勝之家，難與慮敵，吾方自思之。", literal: "\" The emperor laughed and said: \"A house that always wins is hard to consult on the enemy—I am just now thinking it through myself.\"", idiomatic: "\" The emperor smiled. \"A house that never loses is hard to counsel on the foe. I am weighing this myself.\"" },
  { zh: "春，正月，遼東徼外貊人寇邊，太守祭肜招降之。", literal: "In spring, the first month, the Mo people beyond the Liaodong frontier raided the border; the Administrator Cai Yong received their surrender.", idiomatic: "In spring, in the first month, Mo tribes beyond the Liaodong frontier raided the border. Administrator Cai Yong won them by surrender." },
  { zh: "肜又以財利撫納鮮卑大都護偏何，使招致異種，駱驛款塞。", literal: "Yong also with wealth and profit soothed and drew in the Xianbei Grand Protector Pian He, causing him to summon other tribes; they came in continuous streams to the passes in sincerity.", idiomatic: "Yong also won over the Xianbei Grand Protector Pian He with gifts and favors, and had him summon other tribes. Envoys came in an unbroken stream to the frontier passes." },
  { zh: "肜曰：「審欲立功，當歸擊匈奴，斬送頭首，乃信耳。", literal: "Yong said: \"If you truly wish merit, you ought to turn and strike the Xiongnu, behead them, and send the heads—only then is it believed.\"", idiomatic: "Yong told him, \"If you truly want merit, turn on the Xiongnu, strike them down, and send their heads. Only then will we believe you.\"" },
  { zh: "」偏何等即擊匈奴，斬首二千餘級，持頭詣郡。", literal: "\" Pian He and the rest thereupon attacked the Xiongnu, beheaded more than two thousand, and bore the heads to the commandery.", idiomatic: "\" Pian He and his men at once attacked the Xiongnu, took more than two thousand heads, and brought them to the commandery seat." },
  { zh: "其後歲歲相攻，輒送首級，受賞賜。", literal: "Afterward year by year they fought each other and each time sent heads and received rewards.", idiomatic: "Year after year they raided each other, sent heads, and received rewards." },
  { zh: "自是匈奴衰弱，邊無寇警，鮮卑、烏桓並入朝貢。", literal: "From this the Xiongnu grew weak; the borders knew no alarm; Xianbei and Wuhuan alike came to court with tribute.", idiomatic: "From then on the Xiongnu weakened, the frontier knew peace, and Xianbei and Wuhuan alike came to court with tribute." },
  { zh: "肜為人質厚重毅，撫夷狄以恩信，故皆畏而愛之，得其死力。", literal: "Yong was plain, heavy, firm, and resolute; he soothed the tribes with grace and faith, so all feared yet loved him and gave him their strength unto death.", idiomatic: "Yong was plain, grave, and steadfast. He ruled the tribes with grace and good faith, so they feared and loved him alike and gave their lives for him." },
  { zh: "南單于遣其弟左賢王莫將兵萬餘人擊北單于弟薁□建左賢王，生獲之；", literal: "The Southern Chanyu sent his younger brother Left Wise Prince Mo with more than ten thousand troops to attack the Northern Chanyu's younger brother Left Wise Prince of □□jian, and took him alive;", idiomatic: "The Southern Chanyu sent his younger brother, Left Wise Prince Mo, with more than ten thousand men against the Northern Chanyu's younger brother, Left Wise Prince □□jian, and captured him alive;" },
  { zh: "北單于震怖，卻地千餘里。", literal: "the Northern Chanyu was shaken with terror and withdrew his lands more than a thousand li.", idiomatic: "the Northern Chanyu was terrified and pulled back more than a thousand li." },
  { zh: "北部薁□建骨都侯與右骨都侯率眾三萬餘人歸南單于。", literal: "The northern □□jian Gudu Marquis and the Right Gudu Marquis led more than thirty thousand men to submit to the Southern Chanyu.", idiomatic: "The northern □□jian Gudu Marquis and the Right Gudu Marquis led more than thirty thousand men to the Southern Chanyu." },
  { zh: "三月，南單于復遣使詣闕貢獻，求使者監護，遣侍子，修舊約。", literal: "In the third month the Southern Chanyu again sent envoys to court with tribute, asking for an envoy to oversee and protect him, to send a hostage son, and to renew the old covenant.", idiomatic: "In the third month the Southern Chanyu again sent tribute to court, asked for a Han envoy to oversee him, offered a hostage son, and sought to renew the old treaty." },
  { zh: "戊申晦，日有食之。", literal: "On the last day of the cycle, wushen, there was an eclipse of the sun.", idiomatic: "On the last day of the month, wushen, the sun was eclipsed." },
  { zh: "馬援軍至臨鄉，擊破蠻兵，斬獲二千餘人。", literal: "Ma Yuan's army reached Linxiang, broke the tribal troops, and beheaded or captured more than two thousand.", idiomatic: "Ma Yuan's army reached Linxiang, routed the tribesmen, and killed or captured more than two thousand." },
  { zh: "初，援嘗有疾，虎賁中郎將梁松來候之，獨拜床下，援不答。", literal: "Earlier, when Yuan had been ill, the Rapid-as-Tigers Palace Attendant Liang Song came to visit him, bowing alone beside the bed; Yuan did not respond.", idiomatic: "Earlier, when Yuan lay ill, Rapid-as-Tigers Palace Attendant Liang Song came to visit. Song bowed alone beside the bed. Yuan did not return the courtesy." },
  { zh: "鬆去後，諸子問曰：「梁伯孫，帝婿，貴重朝庭，公卿已下莫不憚之，大人奈何獨不為禮？", literal: "\" After Song left, Yuan's sons asked: \"Uncle Liang, the emperor's son-in-law, is weighty in court; from the excellencies down none do not fear him—why did you alone not show him courtesy?\"", idiomatic: "\" After Song left, Yuan's sons asked, \"Uncle Liang is the emperor's son-in-law, a man the whole court fears down to the excellencies. Why did you alone refuse him courtesy?\"" },
  { zh: "」援曰：「我乃松父友也，雖貴，何得失其序乎！", literal: "\" Yuan said: \"I am Song's father's friend; however noble he be, how could one lose the proper order!\"", idiomatic: "\" Yuan said, \"I am your father's friend to Liang Song. However high he stands, how can one abandon proper order?\"" },
  { zh: "援兄子嚴、敦並喜譏議，通輕俠，援前在交趾，還書誡之曰：「吾欲汝曹聞人過失，如聞父母之名，耳可得聞，口不可得言也。", literal: "Yuan's elder brother's sons Yan and Dun both delighted in mockery and debate and were versed in light knight-errantry; when Yuan was earlier in Jiaozhi he sent a letter back admonishing them: \"I wish you all, on hearing others' faults, to be as when hearing your parents' names—the ear may receive it, the mouth may not speak it.\"", idiomatic: "Yuan's nephews Yan and Dun loved gossip and light company. When Yuan was in Jiaozhi he wrote to warn them: \"When you hear of another's fault, treat it as you would your parents' names—the ear may hear it, the mouth must not speak it.\"" },
  { zh: "好論議人長短，妄是非政法，此吾所大惡也，寧死，不願聞子孫有此行也。", literal: "\"To delight in debating others' strengths and shortcomings and recklessly judge right and wrong in law and government—this is what I greatly hate; I would rather die than hear my sons and grandsons have such conduct.\"", idiomatic: "\"To delight in judging others' faults and meddling in public right and wrong—that I hate above all. I would rather die than hear my sons and grandsons do such things.\"" },
  { zh: "龍伯高敦厚周慎，口無擇言，謙約節儉，廉公有威，吾愛之重之，願汝曹效之。", literal: "\"Long Bogao is thick and cautious in all rounds, his mouth without chosen words, humble, restrained, and frugal, upright in public and with authority—I love and weight him; I wish you all to emulate him.\"", idiomatic: "\"Long Bogao is thorough, cautious, and measured in speech—humble, frugal, upright, and commanding respect. I love and honor him. Be like him.\"" },
  { zh: "杜季良豪俠好義，憂人之憂，樂人之樂，父喪致客，數郡畢至，吾愛之重之，不願汝曹效也。", literal: "\"Du Jiliang is bold in knight-errantry and loves righteousness, grieves others' griefs and joys in others' joys; at a father's mourning he gathers guests and several commanderies all arrive—I love and weight him, but I do not wish you all to emulate him.\"", idiomatic: "\"Du Jiliang is bold and righteous, shares others' griefs and joys, and at a father's funeral draws guests from whole commanderies. I love and honor him too, but I do not want you to be like him.\"" },
  { zh: "效伯高不得，猶為謹敕之士，所謂『刻鵠不成尚類鶩』者也；", literal: "\"To emulate Bogao and fall short, one is still a careful and restrained gentleman—what is called 'carve a swan and fail, yet it still resembles a duck.'\"", idiomatic: "\"Fail at emulating Bogao and you are still a careful man—'carve a swan imperfectly and it still looks like a duck.'\"" },
  { zh: "效季良不得，陷為天下輕薄子，所謂『畫虎不成反類狗』者也。", literal: "\"To emulate Jiliang and fall short, one sinks to become the realm's frivolous scoundrel—what is called 'paint a tiger and fail, and instead it resembles a dog.'\"", idiomatic: "\"Fail at emulating Jiliang and you become the realm's frivolous wastrel—'paint a tiger imperfectly and it looks like a dog.'\"" },
  { zh: "」伯高者，山都長龍述也，季良者，越騎司馬杜保也，皆京兆人。", literal: "\" Bogao is Long Shu, magistrate of Shandu; Jiliang is Du Bao, Major of the Exalted Cavalry—all are men of Jingzhao.", idiomatic: "\" Bogao is Long Shu, magistrate of Shandu. Jiliang is Du Bao, Major of the Exalted Cavalry. Both are from Jingzhao." },
  { zh: "會保仇人上書，訟「保為行浮薄，亂群惑眾，伏波將軍萬望還書以誡兄子，而梁松、竇固與之交結，將扇其輕偽，敗亂諸夏。", literal: "\" It happened that Bao's enemy memorialized the throne, accusing: \"Bao's conduct is frivolous and thin; he disorders groups and deludes the masses. General Who Calms the Waves Ma Yuan's letter home admonishing his brother's sons—yet Liang Song and Dou Gu associate with him and will fan his lightness and falsity to ruin and disorder the central states.\"", idiomatic: "\" Then Bao's enemy memorialized the throne: \"Bao is frivolous and seditious. General Who Calms the Waves Ma Yuan wrote home to warn his nephews—yet Liang Song and Dou Gu befriend Bao and will spread his recklessness to corrupt the central realm.\"" },
  { zh: "」書奏，帝召責松、固，以訟書及援誡書示之，松、固叩頭流血，而得不罪。", literal: "\" When the memorial was submitted, the emperor summoned and reproached Song and Gu, showed them the accusation and Yuan's admonition; Song and Gu knocked their heads until they bled and thus escaped punishment.", idiomatic: "\" When the memorial arrived, the emperor summoned Song and Gu, showed them the charge and Yuan's letter. They knocked their heads until they bled and were spared." },
  { zh: "詔免保官，擢拜龍述為零陵太守。", literal: "An edict removed Bao from office and promoted Long Shu to Administrator of Lingling.", idiomatic: "An edict stripped Bao of office and made Long Shu Administrator of Lingling." },
  { zh: "松由是恨援。", literal: "Song from this bore hatred toward Yuan.", idiomatic: "From that day Song hated Yuan." },
  { zh: "及援討武陵蠻，軍次下雋，有兩道可入：從壺頭則路近而水險，從充則塗夷而運遠。", literal: "When Yuan campaigned against the Wuling tribes, the army halted at Xiajun; two routes could enter: by Hutou the road was near but the waters perilous; by Chong the path was level but transport far.", idiomatic: "When Yuan marched against the Wuling tribes, his army halted at Xiajun. Two routes lay open: through Hutou the way was short but the waters deadly; through Chong the ground was easy but supplies a long haul." },
  { zh: "耿舒欲從充道，援以為棄日費糧，不如進壺頭，扼其喉咽，充賊自破。", literal: "Geng Shu wished to take the Chong route; Yuan held that to abandon days and spend grain was inferior to advancing by Hutou, seizing their throat, and the Chong bandits would break of themselves.", idiomatic: "Geng Shu wanted the Chong road. Yuan argued that wasting days and grain was folly—better to drive through Hutou, seize the enemy's throat, and let the Chong rebels collapse on their own." },
  { zh: "以事上之，帝從援策。", literal: "He reported the matter upward; the emperor followed Yuan's plan.", idiomatic: "He reported to the throne, and the emperor backed Yuan's plan." },
  { zh: "進營壺頭，賊乘高守隘，水疾，船不得上。", literal: "Advancing to encamp at Hutou, the bandits held the heights and guarded the narrows; the waters ran fierce and boats could not ascend.", idiomatic: "He advanced and camped at Hutou. The enemy held the heights and the passes. The current ran too fierce for boats to climb." },
  { zh: "會暑甚，士卒多疫死，援亦中病，乃穿岸為室以避炎氣。", literal: "It happened that the heat was extreme; many soldiers died of plague; Yuan too fell ill and thereupon tunneled the bank into chambers to escape the burning air.", idiomatic: "The heat was brutal. Plague killed many soldiers. Yuan fell ill as well and had chambers cut into the riverbank to escape the sun." },
  { zh: "賊每升險鼓噪，援輒曳足以觀之，左右哀其壯意，莫不為之流涕。", literal: "Whenever the bandits climbed the heights and beat drums in clamor, Yuan would drag himself forth on foot to watch; those at his side pitied his stalwart will, and none failed to weep for him.", idiomatic: "Whenever the enemy climbed the heights and beat their drums, Yuan dragged himself up to watch. His attendants pitied his stubborn courage, and none could watch without tears." },
  { zh: "耿舒與兄好畤侯弇書曰：「前舒上書當先擊充，糧雖難運而兵馬得用，軍人數萬，爭欲先奮。", literal: "Geng Shu wrote to his elder brother Marquis of Haozhi Yan: \"Earlier Shu memorialized that one ought first to strike Chong; though grain was hard to transport, troops and horses could be used—several tens of thousands of soldiers all strove to be first in ardor.\"", idiomatic: "Geng Shu wrote his elder brother, Marquis of Haozhi Geng Yan: \"I argued we should strike Chong first. Grain would be hard to haul, but the army could fight—tens of thousands eager to charge.\"" },
  { zh: "今壺頭竟不得進，大眾怫郁行死，誠可痛惜！", literal: "\"Now at Hutou we ultimately cannot advance; the great host is sullen and dying on the march—truly this wrings the heart!\"", idiomatic: "\"Now we cannot advance at Hutou at all. The army sulks and dies on the march. The waste is heartbreaking!\"" },
  { zh: "前到臨鄉，賊無故自致，若夜擊之，即可殄滅。", literal: "\"Before, when we reached Linxiang, the bandits came of themselves for no reason—had we struck by night, we could have extinguished them at once.\"", idiomatic: "\"At Linxiang the enemy offered themselves for no reason. A night attack would have wiped them out.\"" },
  { zh: "伏波類西域賈胡，到一處輒止，以是失利。", literal: "\"The Wave-Calmer is like a Western Regions merchant—wherever he arrives he halts, and for this loses victory.\"", idiomatic: "\"The Wave-Calmer acts like a merchant of the Western Regions—he halts wherever he lands, and that is why we fail.\"" },
  { zh: "今果疾疫，皆如舒言。", literal: "\"Now plague has indeed come—all as Shu said.\"", idiomatic: "\"Now plague has come, just as I warned.\"" },
  { zh: "」弇得書奏之，帝乃使梁松乘驛責問援，因代監軍。", literal: "\" Yan received the letter and memorialized it; the emperor thereupon sent Liang Song by post relay to reproach Yuan and thereby replace him as overseer of the army.", idiomatic: "\" Yan received the letter and sent it to the throne. The emperor dispatched Liang Song by relay post to rebuke Yuan and take over supervision of the army." },
  { zh: "會援卒，松因是構陷援。", literal: "It happened that Yuan died; Song used this to frame and entrap Yuan.", idiomatic: "Yuan died on the campaign. Song used the moment to frame him." },
  { zh: "帝大怒，追收援新息侯印綬。", literal: "The emperor was greatly enraged and pursued the recovery of Yuan's seal and ribbon as Marquis of Xinxin.", idiomatic: "The emperor in fury ordered Yuan's seal and ribbon as Marquis of Xinxin seized." },
  { zh: "初，援在交趾，常餌薏苡實，能輕身，勝障氣，軍還，載之一車。", literal: "Earlier, when Yuan was in Jiaozhi, he constantly ate coix seed, which could lighten the body and overcome miasma; when the army returned he loaded a whole cart.", idiomatic: "Earlier, in Jiaozhi, Yuan had eaten coix seed to lighten his body and resist miasma. On his return he loaded a cart with it." },
  { zh: "及卒後，有上書譖之者，以為前所載還皆明珠文犀。", literal: "After he died someone memorialized to slander him, holding that what he had brought back was all bright pearls and patterned rhinoceros horn.", idiomatic: "After his death a memorial accused him of filling that cart with pearls and rhinoceros horn." },
  { zh: "帝益怒。", literal: "The emperor grew still angrier.", idiomatic: "The emperor's rage deepened." },
  { zh: "援妻孥惶懼，不敢以喪還舊塋，稿葬城西，賓客故人，莫敢吊會。", literal: "Yuan's wife and children were afraid and dared not return the coffin to the old tomb; they buried him in straw rites west of the city; guests and old friends none dared mourn or assemble.", idiomatic: "Yuan's wife and children were terrified and dared not bury him in the family tomb. They laid him in a rough grave west of the city. Not one friend or guest dared mourn him." },
  { zh: "嚴與援妻子草索相連，詣闕請罪。", literal: "Yan, with Yuan's wife and children roped together in straw, went to the court to beg punishment.", idiomatic: "Yan bound himself with straw rope to Yuan's wife and children and went to court to beg mercy." },
  { zh: "帝乃出松書以示之，方知所坐，上書訴冤，前後六上，辭甚哀切。", literal: "The emperor thereupon produced Song's letter to show them; they then knew the crime charged; they memorialized to plead injustice, six times in all, the words very mournful and urgent.", idiomatic: "The emperor showed them Song's letter, and they learned the charge. They memorialized their grief six times, each plea more desperate than the last." },
  { zh: "前雲陽令扶風朱勃詣闕上書曰：「竊見故伏波將軍馬援，拔自西州，欽慕聖義，聞關險難，觸冒萬死，經營隴、冀，謀如湧泉，勢如轉規，兵動有功，師進輒克。", literal: "The former Magistrate of Yunyang Zhu Bo of Fufeng came to court and memorialized: \"Your servant has observed the late General Who Calms the Waves Ma Yuan, raised from the western provinces, admiring in his heart the sage's righteousness, hearing of passes and perils, touching and braving ten thousand deaths, managing Long and Ji—plans like a gushing spring, momentum like a turning compass; when troops moved there was achievement, when the army advanced it always overcame.\"", idiomatic: "Former Magistrate of Yunyang Zhu Bo of Fufeng came to court and wrote: \"Your servant has seen how the late General Who Calms the Waves Ma Yuan rose from the western lands, revered the sage's way, braved passes and ten thousand deaths, and held Long and Ji—his plans gushing like a spring, his momentum wheeling like a compass. Where his army moved, it won. Where it marched, it conquered.\"" },
  { zh: "誅鋤先零，飛矢貫脛，出征交趾，與妻子生訣。", literal: "\"He executed and rooted out the Xianlian; a flying arrow pierced his shank; campaigning in Jiaozhi he took leave of wife and children as if for life.\"", idiomatic: "\"He crushed the Xianlian and took an arrow through the shin. He marched on Jiaozhi and parted from wife and children as from the living dead.\"" },
  { zh: "間復南討，立陷臨鄉，師已有業，未竟而死。", literal: "\"Soon again he campaigned south, at once stormed Linxiang—the army already had achievement, yet before completion he died.\"", idiomatic: "\"He marched south again, took Linxiang at once—the campaign already won—and died before the work was done.\"" },
  { zh: "吏士雖疫，援不獨存。", literal: "\"Though officers and soldiers suffered plague, Yuan did not alone survive.\"", idiomatic: "\"Though plague struck officers and men alike, Yuan did not survive alone.\"" },
  { zh: "夫戰或以久而立功，或以速而致敗，深入未必為得，不進未必為非，人情豈樂久屯絕地不生歸哉！", literal: "\"In war one may through length of time achieve merit, or through haste bring defeat; to drive deep is not necessarily gain, to hold back is not necessarily wrong—would human hearts delight to long encamp in a dead land and not live to return!\"", idiomatic: "\"War sometimes wins by patience and sometimes loses by haste. To march deep is not always wise, nor is holding back always wrong. What man would gladly rot in a dead land with no hope of home?\"" },
  { zh: "惟援得事朝廷二十二年，北出塞漠，南度江海，觸冒害氣，僵死軍事，名滅爵絕，國土不傳，海內不知其過，眾遮未聞其毀，家屬杜門，葬不歸墓，怨隙並興，宗親怖心栗，死者不能自列，生者莫為之訟，臣竊傷之！", literal: "\"Only Yuan served the court twenty-two years, north beyond the desert frontier, south crossing rivers and seas, touching and braving harmful vapors, stiffening dead in military affairs—name extinguished, enfeoffment ended, fief untransmitted; within the seas none know his fault, the many screens have not heard his ruin; his household shut their doors, burial did not return to the tomb; resentments rose together, clan kin feared and trembled in heart—the dead could not clear themselves, the living had none to plead for them—your servant privately grieves!\"", idiomatic: "\"Yuan served the throne twenty-two years—north beyond the desert, south across rivers and seas—braving poison air until war stiffened his limbs. His name is erased, his marquisate stripped, his fief untransmitted. The realm does not know his fault. No voice has reached your ear of his ruin. His kin shut their doors. He lies buried far from his ancestors. Resentment festers. His clan trembles. The dead cannot speak. The living dare not plead. Your servant grieves in secret!\"" },
  { zh: "夫明主□農於用賞，約於用刑，高祖嘗與陳平金四萬斤以間楚軍，不問出入所為，豈復疑以錢谷間哉！", literal: "\"A bright lord □ is diligent in using rewards and restrained in using punishments; Gaozu once gave Chen Ping forty thousand jin of gold to sow discord in the Chu army and did not inquire into comings and goings or what was done—how could he again suspect over money and grain!\"", idiomatic: "\"A wise ruler □ is generous with reward and sparing with punishment. Gaozu once gave Chen Ping forty thousand jin of gold to sow discord in the Chu army and never asked how it was spent—would he then have suspected a cart of grain?\"" },
  { zh: "願下公卿，平援功罪，宜絕宜續，以厭海內之望。", literal: "I wish Your Majesty would send it down to the duke-and-minister ranks to weigh Yuan's merits and faults—whether to cut off or continue—and thereby satisfy the hopes within the seas.", idiomatic: "I ask Your Majesty to refer the case to the chief ministers, weigh Ma Yuan's merits and faults, decide whether to end or continue his line, and satisfy the empire's expectations." },
  { zh: "」帝意稍解。", literal: "\" The emperor's mind was somewhat eased.", idiomatic: "\" The emperor's anger eased somewhat." },
  { zh: "初，勃年十二，能誦《詩》、《書》，常候援兄況，辭言嫻雅，援裁知書，見之自失。", literal: "Earlier, when Bo was twelve he could recite the Odes and Documents; he often attended Yuan's elder brother Kuang; his speech was refined and elegant; Yuan barely knew letters and, seeing him, felt himself lacking.", idiomatic: "Earlier, at twelve Zhu Bo could recite the Odes and Documents. He often visited Ma Yuan's elder brother Kuang; his speech was refined. Ma Yuan, barely literate, felt crude beside him." },
  { zh: "況知其意，乃自酌酒慰援曰：「朱勃小器速成，智盡此耳，卒當從汝稟學，勿畏也。", literal: "Kuang knew his intent and himself poured wine to console Yuan, saying: \"Zhu Bo is a small vessel quick to fill—his wit ends here; in the end he will come study under you—do not fear.\"", idiomatic: "Kuang read his mind and poured wine to console Ma Yuan: \"Zhu Bo is a shallow vessel that fills quickly—his wit goes no further. In the end he will come to learn from you. Do not be afraid.\"" },
  { zh: "」勃未二十，右扶風清試守渭城宰。", literal: "\" Before twenty, Right Fufeng Qing requested him as acting magistrate of Weicheng.", idiomatic: "\" Before he was twenty, Right Fufeng requested him as acting magistrate of Weicheng." },
  { zh: "及援為將軍封侯，而勃位不過縣令。", literal: "When Yuan became a general and was enfeoffed marquis, Bo's rank did not exceed county magistrate.", idiomatic: "When Ma Yuan became a general and was enfeoffed marquis, Zhu Bo's rank never rose above county magistrate." },
  { zh: "援後雖貴，常待以舊恩而卑侮之，勃愈身自親。", literal: "Though Yuan later was noble, he always treated him with old kindness yet humbled and insulted him; Bo became ever more intimate in person.", idiomatic: "Though Ma Yuan later rose high, he still treated Zhu Bo with old familiarity yet humbled and slighted him; Zhu Bo only drew closer." },
  { zh: "及援遇讒，唯勃能終焉。", literal: "When Yuan met slander, only Bo could see him through to the end.", idiomatic: "When Ma Yuan met slander, only Zhu Bo stood by him to the end." },
  { zh: "謁者南陽宗均監援軍，援既卒，軍士疫死者太半，蠻亦饑困。", literal: "Gentleman-in-Attendance Zong Jun of Nanyang supervised Yuan's army; when Yuan had died, more than half the soldiers died of plague; the barbarians too were hungry and distressed.", idiomatic: "Gentleman-in-Attendance Zong Jun of Nanyang supervised Ma Yuan's army. After Ma Yuan died, more than half the soldiers died of plague, and the barbarians too were starving." },
  { zh: "均乃與諸將議曰：「今道遠士病，不可以戰，欲權承製降之，何如？", literal: "Jun thereupon discussed with the generals, saying: \"Now the road is far and the troops sick—we cannot fight; I wish to assume authority and receive the imperial edict to accept their surrender—what of it?\"", idiomatic: "Jun discussed with the generals and said, \"The road is long and the troops are sick—we cannot fight. I wish to assume authority and accept their surrender under the imperial edict. What do you think?\"" },
  { zh: "」諸將皆伏地莫敢應。", literal: "\" The generals all prostrated themselves and dared not answer.", idiomatic: "\" The generals all prostrated themselves and dared not answer." },
  { zh: "均曰：「夫忠臣出竟，有可以安國家，專之可也。", literal: "Jun said: \"A loyal minister beyond the border, if there is something that can secure the state, may act on his own authority.\"", idiomatic: "Jun said, \"A loyal minister beyond the border may act on his own authority when the state can thereby be secured.\"" },
  { zh: "」乃矯制調伏波司馬呂種守沅陵長，命種奉詔書入虜營，告以恩信，因勒兵隨其後。", literal: "\" He thereupon forged an edict transferring Pacification-of-the-Waves Major Lü Zhong to act as chief of Yuanling, ordered Zhong to carry the edict into the enemy camp and announce grace and trust, and then led troops behind him.", idiomatic: "\" He forged an edict appointing Pacification-of-the-Waves Major Lü Zhong acting chief of Yuanling, sent Zhong with the edict into the enemy camp to proclaim grace and trust, and followed with troops." },
  { zh: "蠻夷震怖，冬十月，共斬其大帥而降。", literal: "The barbarians were shaken in terror; in the tenth month of winter they jointly beheaded their great commander and surrendered.", idiomatic: "The barbarians were terrified. In the tenth month of winter they beheaded their great commander and surrendered." },
  { zh: "於是均入賊營，散其眾，遣歸本郡，為置長吏而還，群蠻遂平。", literal: "Thereupon Jun entered the rebel camp, dispersed their masses, sent them back to their native commanderies, set up chief officials for them, and returned—the various barbarians were thus pacified.", idiomatic: "Jun then entered the rebel camp, dispersed the host, sent them home to their commanderies, installed local officials, and returned. The barbarians were pacified." },
  { zh: "均未至，先自劾矯制之罪。", literal: "Before Jun had arrived, he first impeached himself for the crime of forging an edict.", idiomatic: "Before he reached the capital, Jun impeached himself for forging the edict." },
  { zh: "上嘉其功，迎，賜以金帛，令過家上塚。", literal: "The emperor praised his merit, welcomed him, granted gold and silks, and ordered him to pass his home and offer at the ancestral tomb.", idiomatic: "The emperor praised his achievement, welcomed him, granted gold and silks, and allowed him to visit home and tend his family's tomb." },
  { zh: "是歲，遼西烏桓大人郝旦等率眾內屬，詔封烏桓渠帥為侯、王、君長者八十一人，使居塞內，佈於緣邊諸郡，令招來種人，給其衣食，遂為漢偵候，助擊匈奴、鮮卑。", literal: "This year the Wuhuan great men of Liaoxi, Hao Dan and others, led their masses to submit within; an edict enfeoffed eighty-one Wuhuan chieftains as marquises, kings, and clan chiefs, had them dwell inside the passes, spread them among the frontier commanderies, ordered them to summon their tribesmen, supplied food and clothing, and thereby made them Han scouts to help strike the Xiongnu and Xianbei.", idiomatic: "That year the Wuhuan great men of Liaoxi, Hao Dan and others, led their people to submit. The court enfeoffed eighty-one Wuhuan chiefs as marquises, kings, and clan leaders, settled them inside the passes along the frontier commanderies, supplied food and clothing, and made them Han scouts against the Xiongnu and Xianbei." },
  { zh: "時司徒掾班彪上言：「烏桓天性輕黠，好為寇賊，若久放縱而無總領者，必復掠居人，但委主降掾吏，恐非所能制。", literal: "At the time Steward's Clerk Ban Biao submitted: \"The Wuhuan by nature are light and crafty and love to be raiders; if long indulged without an overall commander, they will surely again plunder settlers; to entrust them only to the clerks who receive surrendering chiefs—I fear that cannot control them.\"", idiomatic: "Steward's Clerk Ban Biao submitted: \"The Wuhuan are by nature flighty and crafty and love raiding. If long indulged without an overall commander they will plunder settlers again. Clerks who receive surrendering chiefs alone cannot control them.\"" },
  { zh: "臣愚以為宜復置烏桓校尉，誠有益於附集，省國家之邊慮。", literal: "\"Your servant foolishly holds that it is fitting to restore the Wuhuan Commandant—it truly benefits gathering them in and spares the state's frontier anxieties.\"", idiomatic: "\"I hold that the Wuhuan Commandant should be restored. That would truly help gather them in and spare the state frontier trouble.\"" },
  { zh: "」帝從之，於是始復置校尉於上谷寧城，開營府，並領鮮卑賞賜、質子，歲時互市焉。", literal: "\" The emperor followed this; thereupon he first restored the Commandant at Ningcheng in Shanggu, opened a camp office, and jointly oversaw Xianbei rewards, hostages, and seasonal border markets.", idiomatic: "\" The emperor agreed. The Commandant was restored at Ningcheng in Shanggu, a camp office opened, and he also oversaw Xianbei rewards, hostages, and the seasonal border markets." },
  { zh: "正月，詔增百官奉，其千石已上，減於西京舊制，六百石已下，增於舊秩。", literal: "In the first month an edict increased the salaries of the hundred officials: for those of one thousand bushels and above, reduction from the Western Capital's old standard; for six hundred bushels and below, increase over the old ranks.", idiomatic: "In the first month an edict raised official salaries: ranks of one thousand bushels and above were reduced from the Western Capital standard; ranks of six hundred bushels and below were raised above the old scale." },
  { zh: "初作壽陵。", literal: "Construction of the Shouling tomb was first begun.", idiomatic: "Work began on the Shouling tomb." },
  { zh: "帝曰：「古者帝王之葬，皆陶人、瓦器、木車、茅馬，使後世之人不知其處。", literal: "The emperor said: \"In antiquity the burials of emperors and kings all used pottery figures, earthenware vessels, wooden carts, and straw horses, so that later ages would not know their location.\"", idiomatic: "The emperor said, \"In antiquity imperial burials used pottery figures, earthenware, wooden carts, and straw horses so later ages would not know where they lay.\"" },
  { zh: "太宗識終始之義，景帝能述遵孝道，遭天下反覆，而霸陵獨完受其福，豈不美哉！", literal: "\"Emperor Wen understood the meaning of beginning and end; Emperor Jing could continue and follow filial piety; though the realm turned upside down, Baling alone remained intact and received its blessing—how is that not beautiful!\"", idiomatic: "\"Emperor Wen understood life's beginning and end; Emperor Jing followed his filial example. Though the realm turned upside down, Baling alone stayed intact and reaped the blessing—how fine is that!\"" },
  { zh: "今所制地不過二三頃，無為山陵陂池，裁令流水而已。", literal: "\"The ground now laid out does not exceed two or three qing; do not make hill tombs, pools, or embankments—only allow flowing water.\"", idiomatic: "\"The plot now laid out will not exceed two or three qing. Make no hill tombs, pools, or embankments—only a stream.\"" },
  { zh: "使迭興之後，與丘隴同體。", literal: "\"Let successive rising [dynasties] afterward share the same form as hillocks and mounds.\"", idiomatic: "\"Let later rising [dynasties] share the same plain form as ordinary hillocks.\"" },
  { zh: "」詔遣中郎將段郴、副校尉王郁使南匈奴，立其庭，去五原西部塞八十里。", literal: "\" An edict sent Palace Gentlemen Duan Chen and Deputy Commandant Wang Yu as envoys to the Southern Xiongnu, established their court, eighty li from the western pass of Wuyuan.", idiomatic: "\" An edict sent Palace Gentleman Duan Chen and Deputy Commandant Wang Yu to the Southern Xiongnu, established their court eighty li from the western pass of Wuyuan." },
  { zh: "使者令單于伏拜受詔，單于顧望有頃，乃伏稱臣。", literal: "The envoys ordered the chanyu to prostrate and receive the edict; the chanyu looked about for a while, then prostrated and called himself subject.", idiomatic: "The envoys ordered the chanyu to prostrate and receive the edict. The chanyu hesitated a moment, then prostrated and called himself subject." },
  { zh: "拜訖，令譯曉使者曰：「單于新立，誠慚於左右，願使者眾中無相屈折也。", literal: "When the bow was finished he had the interpreter explain to the envoys: \"The chanyu has newly been established and is truly ashamed before his attendants; I wish the envoys would not bend and break him among the multitude.\"", idiomatic: "When the bow was finished he had the interpreter tell the envoys, \"The chanyu is newly established and is ashamed before his men. I beg the envoys not to humble him before the crowd.\"" },
  { zh: "」詔聽南單于入居雲中，始置使匈奴中郎將，將兵衛護之。", literal: "\" An edict permitted the Southern Chanyu to enter and dwell in Yunzhong; the Envoy-Chanyu Palace Gentlemen was first established to lead troops and guard and protect him.", idiomatic: "\" An edict allowed the Southern Chanyu to dwell in Yunzhong and first established the Envoy to the Xiongnu as Palace Gentlemen to lead troops and guard him." },
  { zh: "夏，南單于所獲北虜薁□建左賢王，將其眾及南部五骨都侯合三萬餘人畔歸，去北庭三百餘里，自立為單于。", literal: "In summer the Northern captive of the Southern Chanyu, the Left Worthy King Ao□jian, led his masses together with the southern five Gudu marquises—more than thirty thousand in all—to rebel and return; three hundred-odd li from the Northern Court he set himself up as chanyu.", idiomatic: "In summer the Northern captive, the Left Worthy King Ao□jian, whom the Southern Chanyu had taken, led his followers and the southern five Gudu marquises—more than thirty thousand men—to rebel and return. Three hundred-odd li from the Northern Court he declared himself chanyu." },
  { zh: "月餘，日更相攻擊，五骨都侯皆死，左賢王自殺，諸骨都侯子各擁兵自守。", literal: "After more than a month they daily attacked one another; the five Gudu marquises all died; the Left Worthy King killed himself; the sons of the various Gudu marquises each held troops and guarded themselves.", idiomatic: "After more than a month they attacked one another daily. The five Gudu marquises all died. The Left Worthy King killed himself. Each son of the Gudu marquises held troops and defended himself." },
  { zh: "秋，南單于遣子入侍。", literal: "In autumn the Southern Chanyu sent his son to attend at court.", idiomatic: "In autumn the Southern Chanyu sent his son to court as hostage." },
  { zh: "詔賜單于冠帶、璽綬、車馬、金帛、甲兵、什器。", literal: "An edict granted the chanyu cap, belt, seal and cord, carriage and horses, gold and silks, armor and weapons, and utensils.", idiomatic: "An edict granted the chanyu cap, belt, seal and cord, carriage and horses, gold and silks, armor, weapons, and utensils." },
  { zh: "又轉河東米□二萬五千斛，牛羊三萬六千頭以贍給之。", literal: "Also transferred from Hedong grain□ twenty-five thousand hu and thirty-six thousand head of cattle and sheep to support and supply him.", idiomatic: "Hedong also sent grain□ twenty-five thousand hu and thirty-six thousand head of cattle and sheep for his support." },
  { zh: "令中郎將將弛刑五十人，隨單于所處，參辭訟，察動靜。", literal: "He ordered the Palace Gentlemen to lead fifty men under commuted punishment, following wherever the chanyu dwelt, to take part in lawsuits and observe movements.", idiomatic: "The Palace Gentlemen were to lead fifty commuted convicts wherever the chanyu dwelt, to assist in lawsuits and watch his movements." },
  { zh: "單于歲盡輒遣奉奏，送侍子入朝，漢遣謁者送前侍子還單于庭，賜單于及閼氏、左、右賢王以下繒彩合萬匹，歲以為常。", literal: "At year's end the chanyu would send tribute memorials and send the attending son to court; Han sent Gentlemen-in-Attendance to escort the former attending son back to the chanyu's court and granted the chanyu, the Yanzhi, the Left and Right Worthy Kings, and those below, brocades and silks totaling ten thousand bolts—yearly as the constant rule.", idiomatic: "At year's end the chanyu sent memorials and the attending son to court. Han sent Gentlemen-in-Attendance to return the former attending son to the chanyu's court and granted the chanyu, the Yanzhi, the Left and Right Worthy Kings, and those below ten thousand bolts of silk yearly as the rule." },
  { zh: "於是雲中、五原、朔方、北地、定襄、雁門、上谷、代八郡民歸於本土。", literal: "Thereupon the people of the eight commanderies—Yunzhong, Wuyuan, Shuofang, Beidi, Dingxiang, Yanmen, Shanggu, and Dai—returned to their native lands.", idiomatic: "Thereupon the people of Yunzhong, Wuyuan, Shuofang, Beidi, Dingxiang, Yanmen, Shanggu, and Dai—the eight commanderies—returned to their native lands." },
  { zh: "遣謁者分將弛刑，補治城郭，發遣邊民在中國者布還諸縣，皆賜以裝錢，轉給糧食。", literal: "He sent Gentlemen-in-Attendance separately to lead commuted convicts, repair city walls, dispatch border people who were in the interior back to the various counties, and all were granted traveling money and grain was transferred to supply them.", idiomatic: "Gentlemen-in-Attendance led commuted convicts to repair the walls, sent border people who had been moved inland back to their counties, granted traveling money to all, and transferred grain for their supply." },
  { zh: "時城郭丘墟，掃地更為，上乃悔前徙之。", literal: "At the time the city walls were ruins; they swept the ground and built anew—the emperor then regretted the earlier relocation.", idiomatic: "The walls were ruins; they swept the ground and rebuilt. The emperor then regretted the earlier relocation." },
  { zh: "冬，南匈奴五骨都侯子復將其眾三千人歸南部，北單于使騎追擊，悉獲其眾。", literal: "In winter a son of the Southern Xiongnu five Gudu marquises again led his mass of three thousand men to return to the southern part; the Northern Chanyu sent horsemen in pursuit and attack and captured all his host.", idiomatic: "In winter a son of the Southern Xiongnu five Gudu marquises again led three thousand men back to the south. The Northern Chanyu sent cavalry in pursuit and captured them all." },
  { zh: "南單于遣兵拒之，逆戰不利，於是復詔單于徙居西河美稷，因使段郴、王郁留西河擁護之，令西河長史歲將騎二千、弛刑五百人助中郎將衛護單于，冬屯夏罷，自後以為常。", literal: "The Southern Chanyu sent troops to resist them; meeting them in battle he did poorly; thereupon an edict again ordered the chanyu to move and dwell at Meiji in Xihe; accordingly Chen and Yu were left in Xihe to support and protect him; the Xihe Chief Clerk yearly was to lead two thousand horse, five hundred commuted convicts, to assist the Palace Gentlemen in guarding the chanyu—winter encampment, summer withdrawal—afterward taken as the constant rule.", idiomatic: "The Southern Chanyu sent troops to resist but fought poorly. An edict then moved the chanyu to Meiji in Xihe. Duan Chen and Wang Yu remained in Xihe to guard him. The Xihe Chief Clerk yearly led two thousand horse and five hundred commuted convicts to help the Palace Gentlemen guard the chanyu—winter encampment, summer withdrawal—thereafter the rule." },
  { zh: "南單于既居西河，亦列置諸部王，助漢扞戍北地、朔方、五原、雲中、定襄、雁門、代郡，皆領部眾，為郡縣偵邏耳目。", literal: "Once the Southern Chanyu had dwelt in Xihe, he also arrayed and set the various tribal kings to help Han garrison Beidi, Shuofang, Wuyuan, Yunzhong, Dingxiang, Yanmen, and Dai—all leading tribal masses as scouts and patrol eyes and ears for the commanderies and counties.", idiomatic: "Once the Southern Chanyu dwelt in Xihe, he also posted tribal kings to help Han garrison Beidi, Shuofang, Wuyuan, Yunzhong, Dingxiang, Yanmen, and Dai. All led their tribes as scouts for the commanderies and counties." },
  { zh: "北單于惶恐，頗還所略漢民以示善意，鈔兵每到南部下，還過亭候，輒謝曰：「自擊亡虜薁□建日逐耳，非敢犯漢民也。", literal: "The Northern Chanyu was fearful and alarmed and largely returned Han people he had seized to show good intent; whenever raiding troops came down to the southern part and on returning passed pavilion posts, he would apologize, saying: \"This was only to strike the dead captive Ao□jian the Rizhu—how would we dare offend Han people.\"", idiomatic: "The Northern Chanyu was alarmed and largely returned seized Han subjects to show goodwill. Whenever raiders came south and passed the frontier posts on their return, he apologized: \"We were only striking the dead captive Ao□jian the Rizhu. We would not dare offend Han subjects.\"" },
  { zh: "夏，四月，戊午，大司徒王況薨。", literal: "In summer, the fourth month, on the day wuwu, Grand Minister of Education Wang Kuang died.", idiomatic: "In summer, in the fourth month, on wuwu day, Grand Minister of Education Wang Kuang died." },
  { zh: "五月，丁丑，詔司徒、司空並去「大」名，改大司馬為太尉。", literal: "In the fifth month, on the day dingchou, an edict ordered the Minister of Education and Minister of Works both to drop the character \"Grand,\" and changed Grand Commander of the Army to Grand Commandant.", idiomatic: "In the fifth month, on dingchou day, an edict dropped \"Grand\" from the titles Minister of Education and Minister of Works and changed Grand Commander of the Army to Grand Commandant." },
  { zh: "驃騎大將軍行大司馬劉隆即日罷，以太僕趙熹為太尉，大司農馮勤為司徒。", literal: "Cavalry General-in-Chief acting as Grand Commander Liu Long was dismissed the same day; Grand Coachman Zhao Xi was made Grand Commandant; Grand Minister of Agriculture Feng Qin was made Minister of Education.", idiomatic: "Cavalry General-in-Chief acting Grand Commander Liu Long was dismissed the same day. Grand Coachman Zhao Xi was made Grand Commandant and Grand Minister of Agriculture Feng Qin Minister of Education." },
  { zh: "北匈奴遣使詣武威求和親，帝召公卿廷議，不決。", literal: "The Northern Xiongnu sent envoys to Wuwei seeking marriage alliance; the emperor summoned the duke-and-minister ranks for court deliberation—they could not decide.", idiomatic: "The Northern Xiongnu sent envoys to Wuwei seeking alliance by marriage. The emperor summoned the chief ministers to court but they could not decide." },
  { zh: "皇太子言曰：「南單于新附，北虜懼於見伐，故傾耳而聽，爭欲歸義耳。", literal: "The heir apparent said: \"The Southern Chanyu has newly submitted; the northern barbarians fear being attacked—therefore they incline their ears and listen, each striving to return to righteousness.\"", idiomatic: "The heir apparent said, \"The Southern Chanyu has newly submitted. The northern barbarians fear attack, so they listen closely and each strives to submit.\"" },
  { zh: "今未能出兵而反交通北虜，臣恐南單于將有二心，北虜降者且不復來矣。", literal: "\"If now we cannot send troops yet turn instead to communicate with the northern barbarians, your servant fears the Southern Chanyu will have two minds and northern barbarians who would surrender will not come again.\"", idiomatic: "\"If we cannot yet send troops but instead deal with the northern barbarians, I fear the Southern Chanyu will waver and northern surrenderers will not come again.\"" },
  { zh: "」帝然之，告武威太守勿受其使。", literal: "\" The emperor approved this and told the Administrator of Wuwei not to receive their envoys.", idiomatic: "\" The emperor agreed and told the Administrator of Wuwei not to receive their envoys." },
  { zh: "朗陵侯臧宮、揚虛侯馬武上書曰：「匈奴貪利，無有禮信，窮則稽首，安則侵盜。", literal: "Marquis of Langling Zang Gong and Marquis of Yangxu Ma Wu submitted memorials, saying: \"The Xiongnu are greedy for profit and have no ritual or trust; when desperate they bow their heads, when secure they invade and rob.\"", idiomatic: "Marquis of Langling Zang Gong and Marquis of Yangxu Ma Wu submitted memorials: \"The Xiongnu are greedy and faithless. Desperate, they bow; secure, they raid.\"" },
  { zh: "虜今人畜疫死，旱蝗赤地，疲睏乏力，不當中國一郡，萬里死命，縣在陛下。", literal: "\"Now their people and livestock die of plague; drought, locusts, and bare red earth; weary, trapped, and without strength—they do not equal one commandery of China; to stake life ten thousand li hangs on Your Majesty.\"", idiomatic: "\"Now their people and livestock die of plague. Drought, locusts, and bare earth have exhausted them. They are weaker than a single Han commandery. Victory ten thousand li away hangs on Your Majesty.\"" },
  { zh: "福不再來，時或易失，豈宜固守文德而墮武事乎！", literal: "\"Fortune does not come twice; the moment may easily be lost—how is it fitting to hold fast to civil virtue and let military affairs fall!\"", idiomatic: "\"Fortune does not come twice and the moment is easily lost. How can we cling to civil virtue and neglect arms?\"" },
  { zh: "今命將臨塞，厚縣購賞，喻告高句驪、烏桓、鮮卑攻其左，發河西四郡、天水、隴西羌、胡擊其右，如此，北虜之滅，不過數年。", literal: "\"Now order generals to the passes, richly post rewards, instruct Gaogouli, Wuhuan, and Xianbei to strike their left; dispatch the four Hexi commanderies and the Qiang and Hu of Tianshui and Longxi to strike their right—thus the northern barbarians' destruction will take no more than a few years.\"", idiomatic: "\"Send generals to the passes with rich rewards. Tell Gaogouli, Wuhuan, and Xianbei to strike their left flank. Send the four Hexi commanderies and the Qiang and Hu of Tianshui and Longxi against their right. The northern barbarians will be destroyed within a few years.\"" },
  { zh: "臣恐陛下仁恩不忍，謀臣狐疑，令萬世刻石之功不立於聖世！", literal: "\"Your servant fears Your Majesty's benevolence and grace will not bear it, counsellors will hesitate in doubt, and the achievement of carving stone for ten thousand ages will not stand in this sage age!\"", idiomatic: "\"I fear Your Majesty's mercy and the ministers' hesitation will leave no stone carved for ten thousand ages in this sage reign!\"" },
  { zh: "」詔報曰：「《黃石公記》曰：『柔能制剛，弱能制強。", literal: "\" An edict replied: \"The Record of Master Yellow Stone says: 'The soft can control the hard; the weak can control the strong.'\"", idiomatic: "\" The edict replied, \"The Record of Master Yellow Stone says, 'The soft can control the hard; the weak can control the strong.'\"" },
  { zh: "捨近謀遠者，勞而無功；", literal: "'To abandon what is near and plot what is far—toil without achievement;'", idiomatic: "'To abandon what is near and plot what is far is toil without achievement;'" },
  { zh: "捨遠謀近者，逸而有終。", literal: "'to abandon what is far and plot what is near—ease and a conclusion.'", idiomatic: "'to abandon what is far and plot what is near brings ease and success.'" },
  { zh: "故曰：務廣地者荒，務廣德者強，有其有者安，貪人有者殘。", literal: "'Therefore it is said: those who strive to broaden territory become desolate; those who strive to broaden virtue become strong; those who possess what they have are secure; those who covet what others have are destructive.'", idiomatic: "'Therefore it is said: those who strive to broaden territory become desolate; those who strive to broaden virtue become strong; those who possess what they have are secure; those who covet what others have are destructive.'" },
  { zh: "殘滅之政，雖成必敗。", literal: "'A policy of destruction and extinction—even if it succeeds, it must fail.'", idiomatic: "'A policy of destruction—even if it succeeds, it must fail.'" },
  { zh: "』今國無善政，災變不息，百姓驚惶，人不自保，而復欲遠事邊外乎！", literal: "'Now the state has no good government; disasters and omens do not cease; the hundred surnames are alarmed and fearful; men cannot preserve themselves—and you again wish to undertake distant affairs beyond the borders!'", idiomatic: "'The state has no good government. Disasters do not cease. The people are terrified and cannot preserve themselves—and you would again undertake distant border campaigns!'" },
  { zh: "孔子曰：『吾恐季孫之憂不在顓臾。", literal: "'Confucius said: \"I fear the distress of Ji Sun is not in Zhuanyu.\"'", idiomatic: "'Confucius said, \"I fear Ji Sun's trouble is not in Zhuanyu.\"'" },
  { zh: "』且北狄尚強，而屯田警備，傳聞之事，恆多失實。", literal: "'Moreover the northern Di are still strong, while garrison farming and alerts multiply; matters heard by report are often not true.'", idiomatic: "'Moreover the northern Di are still strong, and garrison reports are often untrue.'" },
  { zh: "誠能舉下下之半以滅大寇，豈非至願！", literal: "'If one could truly raise half the empire to destroy the great bandits—would that not be the utmost wish!'", idiomatic: "'If we could truly raise half the empire to destroy the great enemy, that would be the utmost wish!'" },
  { zh: "苟非其時，不如息民。", literal: "'If it is not the time, better to let the people rest.'", idiomatic: "'If the time is not right, better to let the people rest.'" },
  { zh: "」自是諸將莫敢復言兵事者。", literal: "\" From this the various generals did not dare again speak of military affairs.", idiomatic: "\" From then on the generals did not dare speak of war again." },
  { zh: "上問趙熹以久長之計，熹請遣諸王就國。", literal: "The emperor asked Zhao Xi about a long-term plan; Xi requested sending the various kings to their states.", idiomatic: "The emperor asked Zhao Xi for a long-term plan. Xi urged sending the princes to their states." },
  { zh: "冬，上始遣魯王興、齊王石就國。", literal: "In winter the emperor first sent the King of Lu, Xing, and the King of Qi, Shi, to their states.", idiomatic: "In winter the emperor first sent the King of Lu, Xing, and the King of Qi, Shi, to their states." },
  { zh: "是歲，帝舅壽張恭侯樊宏薨。", literal: "This year the emperor's maternal uncle, Marquis Gong of Shouzhang, Fan Hong, died.", idiomatic: "That year the emperor's maternal uncle, Marquis Gong of Shouzhang, Fan Hong, died." },
  { zh: "宏為人謙柔畏慎，每當朝會，輒迎期先到，俯伏待事；", literal: "Hong as a man was modest, gentle, fearful, and cautious; whenever there was court assembly he would meet the appointed time and arrive first, prostrating himself to await business;", idiomatic: "Hong was modest, gentle, and cautious. At every court assembly he arrived before the appointed time and waited prostrate;" },
  { zh: "所上便宜，手自書寫，毀削草本；", literal: "memorials he presented on timely advantage he copied in his own hand and destroyed the draft copies;", idiomatic: "he copied his policy memorials in his own hand and destroyed the drafts;" },
  { zh: "公朝訪逮，不敢眾對。", literal: "when the court publicly questioned and pursued him he dared not answer before the multitude.", idiomatic: "when the court questioned him in public he dared not answer before the crowd." },
  { zh: "宗族染其化，未嘗犯法。", literal: "His clan and kindred were dyed by his transformation and never violated the law.", idiomatic: "His clan, touched by his example, never broke the law." },
  { zh: "帝甚重之。", literal: "The emperor greatly valued him.", idiomatic: "The emperor greatly valued him." },
  { zh: "及病困，遺令薄葬，一無所用。", literal: "When critically ill he left instructions for a plain burial, using nothing.", idiomatic: "When gravely ill he ordered a plain burial using nothing superfluous." },
  { zh: "以為棺柩一藏，不宜復見，如有腐敗，傷孝子之心，使與夫人同墳異藏。", literal: "He held that the coffin is one repository and ought not be seen again; if there is decay it wounds the filial son's heart—have him share a mound with his lady but a separate burial repository.", idiomatic: "He held that a coffin is one repository and should not be opened again; decay would wound a filial son's heart. He asked to share a mound with his wife but lie in a separate vault." },
  { zh: "帝善其令，以書示百官，因曰：「今不順壽張侯意，無以彰其德；", literal: "The emperor approved his command, showed it in writing to the hundred officials, and said: \"If now we do not follow Marquis of Shouzhang's intent, we cannot display his virtue;\"", idiomatic: "The emperor approved his will, showed it to the officials, and said, \"If we do not follow the Marquis of Shouzhang's wish we cannot honor his virtue;\"" },
  { zh: "且吾萬歲之後，欲以為式。", literal: "\"moreover after my ten thousand years I wish to take it as a model.\"", idiomatic: "\"and after my ten thousand years I wish to take it as my model.\"" },
  { zh: "春，正月，己巳，徙魯王興為北海王；", literal: "In spring, the first month, on the day jisi, the King of Lu, Xing, was transferred to be King of Beihai;", idiomatic: "In spring, in the first month, on jisi day, the King of Lu, Xing, was moved to be King of Beihai;" },
  { zh: "以魯益東海。", literal: "Lu was added to Donghai.", idiomatic: "Lu was added to Donghai." },
  { zh: "帝以東海王強去就有禮，故優以大封，食二十九縣，賜虎賁、旄頭，設鐘虡之樂，擬於乘輿。", literal: "The emperor because the King of Donghai, Qiang, in going and staying observed ritual, therefore favored him with a great enfeoffment—food from twenty-nine counties—granted Tiger Guards and Plume Head guards, set bell and stand music, matching the imperial carriage.", idiomatic: "Because the King of Donghai, Qiang, observed proper ritual in coming and going, the emperor favored him with a great enfeoffment of twenty-nine counties, Tiger Guards and Plume Head guards, bell and stand music, and trappings matching the imperial carriage." },
  { zh: "夏，六月，丁卯，沛太后郭后薨。", literal: "In summer, the sixth month, on the day dingmao, Empress Dowager Guo of Pei died.", idiomatic: "In summer, in the sixth month, on dingmao day, Empress Dowager Guo of Pei died." },
  { zh: "初，馬援兄子婿王磐，平阿侯仁之子也。", literal: "Earlier, Wang Pan, son-in-law of Ma Yuan's elder brother's son, was son of Marquis Ren of Ping'a.", idiomatic: "Earlier, Wang Pan, Ma Yuan's grandnephew by marriage, was son of Marquis Ren of Ping'a." },
  { zh: "王莽敗，磐擁富貲為遊俠，有名江、淮間。", literal: "When Wang Mang was defeated, Pan amassed wealth and became a roaming knight, famous between the Yangzi and Huai.", idiomatic: "When Wang Mang fell, Pan used his wealth to become a roaming knight famous between the Yangzi and Huai." },
  { zh: "後游京師，與諸貴戚友善，援謂姊子曹訓曰：「王氏，廢姓也，子石當屏居自守，而反游京師長者，用氣自行，多所陵折，其敗必也。", literal: "Later he roamed the capital, befriending various noble kin; Yuan told his sister's son Cao Xun: \"The Wang clan is a deposed surname; Zishi ought to withdraw and keep himself, yet instead he roams the capital's elders, acts by force of temper, and often overrides and breaks others—his defeat is certain.\"", idiomatic: "Later he roamed the capital and befriended the nobles. Ma Yuan told his sister's son Cao Xun, \"The Wangs are a deposed house. Zishi should withdraw and keep to himself, yet he roams among the capital's elders, acts by force, and often humiliates others—his ruin is certain.\"" },
  { zh: "」後歲餘，磐坐事死；", literal: "\" More than a year later Pan died in a criminal case;", idiomatic: "\" A little over a year later Pan died in a criminal case;" },
  { zh: "磐子肅復出入王侯邸第。", literal: "Pan's son Su again went in and out of the mansions of kings and marquises.", idiomatic: "Pan's son Su again frequented the mansions of kings and marquises." },
  { zh: "時禁罔尚疏，諸王皆在京師，競修名譽，招游士。", literal: "At the time prohibitions were still loose; the various kings were all in the capital, competing to cultivate reputation and recruiting roaming scholars.", idiomatic: "Prohibitions were still loose; the princes were all in the capital, competing for reputation and recruiting roaming scholars." },
  { zh: "馬援謂司馬呂種曰：「建武之元，名為天下重開，自今以往，海內日當安耳。", literal: "Ma Yuan told Major Lü Zhong: \"In the first year of Jianwu it was named that the realm was reopened; from now on within the seas day by day ought to be secure.\"", idiomatic: "Ma Yuan told Major Lü Zhong, \"Jianwu's first year marked the realm's reopening. From now on the empire should grow more secure day by day.\"" },
  { zh: "但憂國家諸子並壯而舊防未立，若多通賓客，則大獄起矣。", literal: "\"Only I worry that the state's various sons are all grown while the old defenses are not yet set—if they widely receive guests, then a great prison case will arise.\"", idiomatic: "\"I only worry that the imperial sons are grown while the old safeguards are not yet set. If they receive many guests, a great prison case will arise.\"" },
  { zh: "卿曹戒慎之！", literal: "\"You all must warn and be cautious!\"", idiomatic: "\"You must all take warning!\"" },
  { zh: "」至是，有上書告肅等受誅之家，為諸王賓客，慮因事生亂。", literal: "\" By this time someone submitted a memorial reporting Su and others of families that had suffered execution serving as guests of the various kings—fearing that through events disorder would arise.", idiomatic: "\" By then someone memorialized that Su and others from executed families were serving as princes' guests, fearing disorder might arise." },
  { zh: "會更始之子壽光侯鯉得幸於沛王，怨劉盆子，結客殺故式侯恭。", literal: "It happened that the son of Emperor Gengshi, Marquis Li of Shouguang, gained favor with the King of Pei; he resented Liu Penzi and with guests killed the former Marquis Gong of Shi.", idiomatic: "The son of Emperor Gengshi, Marquis Li of Shouguang, had gained favor with the King of Pei. Resenting Liu Penzi, he and his guests killed the former Marquis Gong of Shi." },
  { zh: "帝怒，沛王坐系詔獄，三日乃得出。", literal: "The emperor was angry; the King of Pei was detained in the edict prison and only after three days was released.", idiomatic: "The emperor was angry. The King of Pei was held in the edict prison and released only after three days." },
  { zh: "因詔郡縣收捕諸王賓客，更相牽引，死者以千數；", literal: "Thereupon an edict ordered commanderies and counties to seize the various kings' guests; they implicated one another in succession; the dead numbered in the thousands;", idiomatic: "An edict then ordered commanderies and counties to seize the princes' guests. Mutual implication followed and thousands died;" },
  { zh: "呂種亦與其禍，臨命歎曰：「馬將軍誠神人也！", literal: "Lü Zhong also met this disaster; facing death he sighed: \"General Ma was truly a spirit man!\"", idiomatic: "Lü Zhong shared the disaster. Facing death he sighed, \"General Ma was truly a prophet!\"" },
  { zh: "秋，八月，戊寅，東海王強、沛王輔、楚王英、濟南王康、淮陽王延始就國。", literal: "In autumn, the eighth month, on the day wuyin, the King of Donghai Qiang, King of Pei Fu, King of Chu Ying, King of Jinan Kang, and King of Huaiyang Yan first went to their states.", idiomatic: "In autumn, in the eighth month, on wuyin day, the Kings of Donghai, Pei, Chu, Jinan, and Huaiyang—Qiang, Fu, Ying, Kang, and Yan—first went to their states." },
  { zh: "上大會群臣，問：「誰可傅太子者？", literal: "The emperor held a great assembly of the ministers and asked: \"Who can tutor the heir apparent?\"", idiomatic: "The emperor held a great assembly of ministers and asked, \"Who can tutor the heir apparent?\"" },
  { zh: "」群臣承望上意，皆言太子舅執金吾原鹿侯陰識可。", literal: "\" The ministers, reading the emperor's intent, all said the crown prince's maternal uncle, Bearer of the Mace, Marquis of Yuanlu Yin Shi, would do.", idiomatic: "\" The ministers, reading the emperor's intent, all said the crown prince's maternal uncle, Bearer of the Mace, Marquis of Yuanlu Yin Shi, would do." },
  { zh: "博士張佚正色曰：「今陛下立太子，為陰氏乎，為天下乎？", literal: "Erudite Zhang Yi said with a stern countenance: \"Now Your Majesty is establishing the heir apparent—is it for the Yin clan, or for the realm?\"", idiomatic: "Erudite Zhang Yi said sternly, \"Your Majesty is establishing the heir apparent—is it for the Yin clan, or for the realm?\"" },
  { zh: "即為陰氏，則陰侯可；", literal: "\"If for the Yin clan, then the Marquis of Yin will do;\"", idiomatic: "\"If for the Yin clan, then the Marquis of Yin will do;\"" },
  { zh: "為天下，則固宜用天下之賢才！", literal: "\"if for the realm, then one should use the realm's worthy talents!\"", idiomatic: "\"if for the realm, one should use the realm's worthy talents!\"" },
  { zh: "」帝稱善，曰：「欲置傅者，以輔太子也；", literal: "\" The emperor approved and said: \"In wishing to appoint a tutor, it is to assist the crown prince;\"", idiomatic: "\" The emperor approved and said, \"In wishing to appoint a tutor, it is to assist the crown prince;\"" },
  { zh: "今博士不難正朕，況太子乎！", literal: "\"now the erudite does not shrink from correcting me—how much more the crown prince!\"", idiomatic: "\"now the erudite does not shrink from correcting me—how much more the crown prince!\"" },
  { zh: "」即拜佚為太子太傅，以博士桓榮為少傅，賜以輜車、乘馬。", literal: "\" He at once appointed Yi as Grand Tutor of the Heir Apparent and Erudite Huan Rong as Junior Tutor, granting a covered carriage and riding horses.", idiomatic: "\" He at once appointed Yi as Grand Tutor of the Heir Apparent and Erudite Huan Rong as Junior Tutor, granting a covered carriage and riding horses." },
  { zh: "榮大會諸生，陳其車馬、印綬，曰：「今日所蒙，稽古之力也，可不勉哉！", literal: "Rong gathered the students in great assembly, displayed his carriage, horses, seals and cords, and said: \"What I am honored with today is the strength of studying antiquity—should we not strive!\"", idiomatic: "Rong gathered the students in great assembly, displayed his carriage, horses, seals, and cords, and said, \"What I am honored with today is the strength of studying antiquity—should we not strive!\"" },
  { zh: "北匈奴遣使貢馬及裘，更乞和親，並請音樂，又求率西域諸國胡客俱獻見。", literal: "The Northern Xiongnu sent envoys presenting horses and furs, again requesting heqin marriage alliance, also requesting music, and further asking to lead the various Western Region states' barbarian guests all to present themselves in audience.", idiomatic: "The Northern Xiongnu sent envoys presenting horses and furs, again requesting heqin marriage alliance, also requesting music, and further asking to lead the various Western Region states' barbarian guests all to present themselves in audience." },
  { zh: "帝下三府議酬答之宜，司徒掾班彪曰：「臣聞孝宣皇帝敕邊守尉曰：『匈奴大國，多變詐，交接得其情，則卻敵折衝；", literal: "The emperor sent down to the Three Offices to deliberate appropriate response. Steward's Clerk Ban Biao said: \"Your servant has heard that Emperor Xuan ordered border guards and commandants: 'The Xiongnu are a great state, much given to shifting deceit—if in dealings you grasp their disposition, you repel the enemy and break their charge;\"", idiomatic: "The emperor sent the matter to the Three Offices to deliberate an appropriate response. Steward's Clerk Ban Biao said, \"Your servant has heard that Emperor Xuan ordered border guards and commandants: 'The Xiongnu are a great state, much given to shifting deceit—if in dealings you grasp their disposition, you repel the enemy and break their charge;\"" },
  { zh: "應對入其數，則反為輕欺。", literal: "'if in reply you fall into their schemes, you are instead lightly deceived.'", idiomatic: "'if in reply you fall into their schemes, you are instead lightly deceived.'\"" },
  { zh: "』今北匈奴見南單于來附，懼謀其國，故數乞和親，又遠驅牛馬與漢合市，重遣名王，多所貢獻，斯皆外示富強以相欺誕也。", literal: "'Now the Northern Xiongnu see the Southern Chanyu come to attach themselves and fear plots against their state—therefore they repeatedly seek heqin, also drive cattle and horses from afar to joint market with Han, repeatedly send famous kings, and make many gifts—all outward shows of strength to deceive.'", idiomatic: "'Now the Northern Xiongnu see the Southern Chanyu come to attach themselves and fear plots against their state—therefore they repeatedly seek heqin, also drive cattle and horses from afar to joint market with Han, repeatedly send famous kings, and make many gifts—all outward shows of strength to deceive.'\"" },
  { zh: "臣見其獻益重，知其國益虛；", literal: "\"Your servant sees their gifts growing heavier and knows their state grows emptier;\"", idiomatic: "\"I see their gifts growing heavier and know their state grows emptier;\"" },
  { zh: "歸親愈數，為懼愈多。", literal: "\"heqin requests more frequent, fear all the greater.\"", idiomatic: "\"heqin requests more frequent, and fear all the greater.\"" },
  { zh: "然今既未獲助南，則亦不宜絕北，羈縻之義，禮無不答。", literal: "\"Yet now since we have not yet obtained aid for the south, we also should not cut off the north—in the sense of keeping on the leash, ritual leaves nothing unanswered.\"", idiomatic: "\"Yet since we have not yet obtained aid for the south, we also should not cut off the north—in the sense of keeping them on the leash, ritual leaves nothing unanswered.\"" },
  { zh: "謂可頗加賞賜，略與所獻相當，報答之辭，令必有適。", literal: "\"I suggest we can add rewards somewhat matching their gifts; the reply's wording should have suitable measure.\"", idiomatic: "\"I suggest we add rewards roughly matching their gifts, and that the reply's wording have suitable measure.\"" },
  { zh: "今立稿草並上，曰：『單于不忘漢恩，追念先祖舊約，欲修和親以輔身安國，計議甚高，為單于嘉之！", literal: "\"I now draft and submit together: 'The Chanyu does not forget Han's grace, recalls the forefathers' old covenant, wishes to renew heqin to support the body and settle the state—the plan is very lofty; the Chanyu is commended!\"", idiomatic: "\"I now draft and submit together: 'The Chanyu does not forget Han's grace, recalls the forefathers' old covenant, wishes to renew heqin to support the body and settle the state—the plan is very lofty; the Chanyu is commended!'\"" },
  { zh: "往者匈奴數有乖亂，呼韓邪、郅支自相仇戾，自絕皇澤，而呼韓附親，忠孝彌著。", literal: "'Formerly the Xiongnu several times had disorder; Huhanxie and Zhijhi mutually hated, cut themselves off from the imperial font—yet Huhanxie attached in kinship, loyalty and filial piety all the more evident.", idiomatic: "'Formerly the Xiongnu several times fell into disorder; Huhanxie and Zhijhi hated one another and cut themselves off from the imperial font—yet Huhanxie attached in kinship, and loyalty and filial piety stood out all the more." },
  { zh: "及漢滅郅支，遂保國傳嗣，子孫相繼。", literal: "When Han destroyed Zhijhi, they thereupon preserved the state and passed the succession, sons and grandsons in continuity.", idiomatic: "When Han destroyed Zhijhi, they preserved the state and passed the succession, sons and grandsons in continuity." },
  { zh: "今南單于攜眾向南，款塞歸命，自以呼韓嫡長，次第當立，而侵奪失職，猜疑相背，數請兵將，歸掃北庭，策謀紛紜，無所不至。", literal: "Now the Southern Chanyu led his masses south, knocked at the passes and submitted, holding himself Huhanxie's legitimate eldest and in order fit to stand—yet was robbed of position; suspicion turned them apart; repeatedly requested troops and generals to return and sweep the northern court—schemes and plans in confusion, nothing they did not reach.", idiomatic: "Now the Southern Chanyu led his masses south, knocked at the passes and submitted, holding himself Huhanxie's legitimate eldest and fit to stand in order—yet was robbed of position; suspicion turned them apart; he repeatedly requested troops and generals to return and sweep the northern court—schemes and plans in confusion, nothing they did not reach." },
  { zh: "惟念斯言不可獨聽，又以北單于比年貢獻，欲修和親，故拒而未許，將以成單于忠孝之義。", literal: "Only reflecting that such words could not be heeded alone, and also that the Northern Chanyu these years has presented tribute and wishes heqin—therefore refused and did not permit, intending thereby to complete the Chanyu's loyalty and filial piety.", idiomatic: "Only reflecting that such words could not be heeded alone, and also that the Northern Chanyu these years has presented tribute and wishes heqin—therefore he refused and did not permit it, intending thereby to complete the Chanyu's loyalty and filial piety." },
  { zh: "漢秉威信，總率萬國，日月所照，皆為臣妾，殊俗百蠻，義無親疏，服順者褒賞，畔逆者誅罰，善惡之效，呼韓、郅支是也。", literal: "Han holds authority and trust, directs all states under heaven; where sun and moon shine, all are subjects and concubines; strange customs and the hundred barbarians—righteousness knows no near or far; those who submit are rewarded and praised, rebels are punished—effect of good and evil: Huhanxie and Zhijhi are the proof.", idiomatic: "Han holds authority and trust and directs all states under heaven; where sun and moon shine, all are subjects; strange customs and the hundred barbarians—righteousness knows no near or far; those who submit are rewarded and praised, rebels are punished—the effect of good and evil: Huhanxie and Zhijhi are the proof." },
  { zh: "今單于欲修和親，款誠已達，何嫌而欲率西域諸國俱來獻見！", literal: "Now the Chanyu wishes heqin; sincere intent has arrived—what scruple in wishing to lead the Western Region states all to come present audience!", idiomatic: "Now the Chanyu wishes heqin and sincere intent has arrived—what scruple in wishing to lead the Western Region states all to come present audience!" },
  { zh: "西域國屬匈奴與屬漢何異！", literal: "Western Region states belonging to the Xiongnu—how do they differ from belonging to Han!", idiomatic: "Western Region states belonging to the Xiongnu—how do they differ from belonging to Han!" },
  { zh: "單于數連兵亂，國內虛耗，貢物裁以通禮，何必獻馬裘！", literal: "The Chanyu has repeatedly linked arms in disorder; within the state is waste and depletion—tribute need only fulfill ritual communication—why must you present horses and furs!", idiomatic: "The Chanyu has repeatedly linked arms in disorder; within the state is waste and depletion—tribute need only fulfill ritual communication—why must you present horses and furs!" },
  { zh: "今繼雜繒五百匹，弓鞬韣丸一，矢四發，遺單于；", literal: "Now as sequel: mixed silks five hundred bolts, one bow case with quiver ball, arrows four bundles, sent to the Chanyu;", idiomatic: "Now as sequel: five hundred bolts of mixed silks, one bow case with quiver ball, four bundles of arrows, sent to the Chanyu;" },
  { zh: "又賜獻馬左骨都侯、右谷蠡王雜繒各四百匹，斬馬劍各一。", literal: "Also granted to the horse-presenting Left Gudu Marquis and Right Guli King mixed silks four hundred bolts each, horse-slaying swords one each.", idiomatic: "Also granted to the horse-presenting Left Gudu Marquis and Right Guli King four hundred bolts of mixed silks each and one horse-slaying sword each." },
  { zh: "單于前言「先帝時所賜呼韓邪竽、瑟、空侯皆敗，願復裁賜。", literal: "The Chanyu formerly said: 'What the former emperor granted Huhanxie—konghou, se, and konghou lute—all are ruined; wish again to receive bestowal according to measure.", idiomatic: "The Chanyu formerly said, 'What the former emperor granted Huhanxie—the konghou, se, and konghou lute—are all ruined; I wish again to receive bestowal according to measure." },
  { zh: "」念單于國尚未安，方厲武節，以戰攻為務，竽瑟之用，不如良弓利劍，故未以繼。", literal: "\" Reflecting the Chanyu's state is not yet settled, now exalting martial discipline with battle and attack as the task—the use of konghou and se is not like good bows and sharp swords; therefore not continued as sequel.", idiomatic: "\" Reflecting that the Chanyu's state is not yet settled and he now exalts martial discipline with battle and attack as the task—the use of konghou and se is not like good bows and sharp swords; therefore they were not continued as sequel." },
  { zh: "朕不愛小物，於單于便宜所欲，遣驛以聞。", literal: "We do not begrudge small things—whatever suits the Chanyu's convenience in desire, send express to report.", idiomatic: "We do not begrudge small things—whatever suits the Chanyu's convenience, send express to report." },
  { zh: "』」聞悉納從之。", literal: "' On hearing, all accepted and followed.", idiomatic: "' On hearing, all accepted and followed." },
  { zh: "春，二月，丁巳朔，日有食之。", literal: "In spring, the second month, on the first day of the month dingsi, there was an eclipse of the sun.", idiomatic: "In spring, in the second month, on the first day of the month, dingsi day, there was a solar eclipse." },
  { zh: "春，二月，車駕東巡。", literal: "In spring, the second month, the imperial carriage toured east.", idiomatic: "In spring, in the second month, the imperial carriage toured east." },
  { zh: "群臣上言：「即位三十年，宜封禪泰山。", literal: "The ministers submitted: \"Thirty years since Your Majesty's accession—it is fitting to feng and shan at Mount Tai.\"", idiomatic: "The ministers submitted, \"Thirty years since Your Majesty's accession—it is fitting to perform feng and shan at Mount Tai.\"" },
  { zh: "」詔曰：「即位三十年，百姓怨氣滿腹，『吾誰欺，欺天乎！", literal: "\" An edict said: \"Thirty years since accession—the common people's resentful breath fills their bellies. 'Whom would I deceive—deceive Heaven?'", idiomatic: "\" An edict ran, \"Thirty years since accession—the common people's resentful breath fills their bellies. 'Whom would I deceive—deceive Heaven?'\"" },
  { zh: "』『曾謂泰山不如林放乎！", literal: "' 'Did one not say Mount Tai is not the equal of Lin Fang!'", idiomatic: "' 'Did one not say Mount Tai is not the equal of Lin Fang!'\"" },
  { zh: "』何事污七十二代之編錄！", literal: "' 'Why pollute the compiled records of seventy-two generations!'", idiomatic: "' 'Why pollute the compiled records of seventy-two generations!'\"" },
  { zh: "若郡縣遠遣吏上壽，盛稱虛美，必髡，令屯田。", literal: "If commanderies and counties far send officials offering longevity congratulations with extravagant false praise—they will be tonsured and ordered to garrison agriculture.\"", idiomatic: "If commanderies and counties far send officials offering longevity congratulations with extravagant false praise, they will be tonsured and ordered to garrison agriculture.\"" },
  { zh: "」於是群臣不敢復言。", literal: "\" Thereupon the ministers did not dare speak again.", idiomatic: "\" Thereupon the ministers did not dare speak again." },
  { zh: "甲子，上幸魯濟南；", literal: "On the day jiazi, the emperor visited Lu and Jinan;", idiomatic: "On jiazi day the emperor visited Lu and Jinan;" },
  { zh: "閏月，癸丑，還宮。", literal: "In the intercalary month, on the day guichou, he returned to the palace.", idiomatic: "In the intercalary month, on guichou day, he returned to the palace." },
  { zh: "有星孛於紫宮。", literal: "A comet appeared in the Purple Palace.", idiomatic: "A comet appeared in the Purple Palace." },
  { zh: "夏，四月，戊子，徙左翊王焉為中山王。", literal: "In summer, the fourth month, on the day wuzi, Left Yi King Yan was moved to King of Zhongshan.", idiomatic: "In summer, in the fourth month, on wuzi day, Left Yi King Yan was made King of Zhongshan." },
  { zh: "五月，大水。", literal: "In the fifth month, great floods.", idiomatic: "In the fifth month there were great floods." },
  { zh: "秋，七月，丁酉，上行幸魯；", literal: "In autumn, the seventh month, on the day dingyou, the emperor went, favoring Lu;", idiomatic: "In autumn, in the seventh month, on dingyou day, the emperor went to Lu;" },
  { zh: "冬，十一月，丁酉，還宮。", literal: "In winter, the eleventh month, on the day dingyou, he returned to the palace.", idiomatic: "In winter, in the eleventh month, on dingyou day, he returned to the palace." },
  { zh: "膠東剛侯賈復薨。", literal: "Marquis Gang of Jiaodong Jia Fu died.", idiomatic: "Marquis Gang of Jiaodong Jia Fu died." },
  { zh: "復從征伐，未嘗喪敗，數與諸將潰圍解急，身被十二創。", literal: "Fu followed campaigns and was never defeated in loss; several times with various generals broke encirclements and relieved emergencies—his body bore twelve wounds.", idiomatic: "Fu followed the campaigns and was never defeated; several times with various generals he broke encirclements and relieved emergencies—his body bore twelve wounds." },
  { zh: "帝以復敢深入，希令遠征，而壯其勇節，常自從之，故復光方面之勳。", literal: "The emperor because Fu dared deep penetration rarely ordered him on distant campaigns, yet admired his courage and integrity, often personally followed him—therefore Fu's glory on his own front was meritorious.", idiomatic: "Because Fu dared deep penetration the emperor rarely ordered him on distant campaigns, yet admired his courage and integrity and often personally followed him—therefore Fu's glory on his own front was meritorious." },
  { zh: "諸將每論功伐，復未嘗有言，帝輒曰：「賈君之功，我自知之。", literal: "Whenever the generals discussed merit for rewards, Fu never spoke—the emperor would say: \"Lord Jia's merit—I know it myself.\"", idiomatic: "Whenever the generals discussed merit for rewards, Fu never spoke—the emperor would say, \"Lord Jia's merit—I know it myself.\"" },
  { zh: "夏，五月，大水。", literal: "In summer, the fifth month, great floods.", idiomatic: "In summer, in the fifth month, there were great floods." },
  { zh: "癸酉晦，日有食之。", literal: "On the last day of the month guiyou, there was an eclipse of the sun.", idiomatic: "On the last day of the month, guiyou day, there was a solar eclipse." },
  { zh: "蝗。", literal: "Locusts.", idiomatic: "Locusts." },
  { zh: "京兆掾第五倫領長安市，公平廉介，市無奸枉。", literal: "Capital District Clerk Diwu Lun supervised Chang'an city—fair, incorruptible, upright; the market had no crooked wrongs.", idiomatic: "Capital District Clerk Diwu Lun supervised Chang'an city—fair, incorruptible, and upright; the market had no crooked wrongs." },
  { zh: "每讀詔書，常歎息曰：「此聖主也，一見決矣。", literal: "Whenever reading edicts, he would sigh and say: \"This is a sage ruler—one meeting and it is decided.\"", idiomatic: "Whenever he read edicts he would sigh and say, \"This is a sage ruler—one meeting and it is decided.\"" },
  { zh: "」等輩笑之曰：「爾說將尚不能下，安能動萬乘乎！", literal: "\" His peers laughed: \"Your persuasion cannot even overcome the commandant—how can you move the lord of ten thousand chariots!\"", idiomatic: "\" His peers laughed and said, \"Your persuasion cannot even overcome the commandant—how can you move the lord of ten thousand chariots!\"" },
  { zh: "」倫曰：「未遇知己，道不同故耳。", literal: "\" Lun said: \"I have not met one who knows me—our ways differ, that is all.\"", idiomatic: "\" Lun said, \"I have not met one who knows me—our ways differ, that is all.\"" },
  { zh: "」後舉孝廉，補淮陽王醫工長。", literal: "\" Later recommended as Filial and Incorrupt, appointed Chief Medical Artisan of the King of Huaiyang.", idiomatic: "\" Later recommended as Filial and Incorrupt, he was appointed Chief Medical Artisan of the King of Huaiyang." },
  { zh: "春，正月，淮陽王入朝，倫隨官屬得會見。", literal: "In spring, the first month, the King of Huaiyang entered court; Lun following the officials obtained audience.", idiomatic: "In spring, in the first month, the King of Huaiyang entered court; Lun, following the officials, obtained audience." },
  { zh: "帝問以政事，倫因此酬對，帝大悅；", literal: "The emperor asked about governmental affairs; Lun thereupon responded—the emperor greatly pleased;", idiomatic: "The emperor asked about governmental affairs; Lun thereupon responded, and the emperor was greatly pleased;" },
  { zh: "明日，復特召入，與語至夕。", literal: "Next day, again specially summoned in, conversed until evening.", idiomatic: "The next day he was again specially summoned in and conversed with him until evening." },
  { zh: "帝謂倫曰：「聞卿為吏，篣婦公，不過從兄飯，寧有之邪？", literal: "The emperor said to Lun: \"I hear when you were an official, bamboo-woven mat for wife's father, would not exceed eating at elder cousin's—can it be?\"", idiomatic: "The emperor said to Lun, \"I hear that when you were an official you used a bamboo-woven mat for your wife's father and would not exceed eating at your elder cousin's—can that be?\"" },
  { zh: "」對曰：「臣三娶妻，皆無父。", literal: "\" He replied: \"Your servant thrice took wives—all without fathers.", idiomatic: "\" He replied, \"Your servant thrice took wives—all without fathers." },
  { zh: "少遭饑亂，實不敢妄過人食。", literal: "In youth suffered famine and disorder—truly dared not recklessly exceed another's food.\"", idiomatic: "In youth I suffered famine and disorder and truly dared not recklessly exceed another's food.\"" },
  { zh: "眾人以臣愚蔽，故生是語耳。", literal: "The crowd, considering your servant stupid and concealing, therefore produced such talk.\"", idiomatic: "The crowd, considering your servant stupid and concealing, therefore produced such talk.\"" },
  { zh: "」帝大笑。", literal: "\" The emperor laughed greatly.", idiomatic: "\" The emperor laughed greatly." },
  { zh: "以倫為扶夷長，未到官，追拜會稽太守；", literal: "He made Lun Chief of Fuyi; before reaching office, pursued appointment as Administrator of Kuaiji;", idiomatic: "He made Lun Chief of Fuyi; before he reached office, he was pursued and appointed Administrator of Kuaiji;" },
  { zh: "為政清而有惠，百姓愛之。", literal: "In government he was pure yet had kindness—the people loved him.", idiomatic: "In government he was pure yet kind, and the people loved him." },
  { zh: "上讀《河圖會昌符》曰；", literal: "The emperor read the *Hetu Huichang Fu*, which says;", idiomatic: "The emperor read the *Hetu Huichang Fu*, which says;" },
  { zh: "「赤劉之九，會命岱宗。", literal: "\"The ninth of the Red Liu—will fate Mount Dai.\"", idiomatic: "\"The ninth of the Red Liu—will fate Mount Dai.\"" },
  { zh: "」上感此文，乃詔虎賁中郎將梁松等按索《河》、《雒》讖文，言九世當封禪者凡三十六事。", literal: "\" Moved by this text, he then ordered Tiger-Gallant Center Commandant Liang Song and others to search the River and Luo apocrypha—sayings that the ninth generation should fengshan totaled thirty-six matters.", idiomatic: "\" Moved by this text, he then ordered Tiger-Gallant Center Commandant Liang Song and others to search the River and Luo apocrypha—sayings that the ninth generation should perform fengshan totaled thirty-six matters." },
  { zh: "於是張純等復奏請封禪，上乃許焉。", literal: "Thereupon Zhang Chun and others again memorialized requesting fengshan; the emperor then permitted it.", idiomatic: "Thereupon Zhang Chun and others again memorialized requesting fengshan, and the emperor then permitted it." },
  { zh: "詔有司求元封故事，當用方石再累，玉檢、金泥。", literal: "An edict ordered the offices to seek Yuanfeng precedents—should use square stones heaped in layers, jade slips, gold mud.", idiomatic: "An edict ordered the offices to seek Yuanfeng precedents—they should use square stones heaped in layers, jade slips, and gold mud." },
  { zh: "上以石功難就，欲因孝武故封石，置玉牒其中。", literal: "The emperor because the stone work was hard to complete wished to use Emperor Wu's former feng stone and place the jade covenant within.", idiomatic: "Because the stone work was hard to complete, the emperor wished to use Emperor Wu's former feng stone and place the jade covenant within it." },
  { zh: "梁松爭以為不可，乃命石工取完青石，無必五色。", literal: "Liang Song contended it could not be done—thereupon ordered stoneworkers to take finished blue-green stone, not necessarily five colors.", idiomatic: "Liang Song contended it could not be done, and stoneworkers were ordered to take finished blue-green stone, not necessarily of five colors." },
  { zh: "丁卯，車駕東巡。", literal: "On the day dingmao, the imperial carriage toured east.", idiomatic: "On dingmao day the imperial carriage toured east." },
  { zh: "二月，己卯，幸魯，進幸泰山。", literal: "In the second month, on the day jimao, favored Lu, advanced to favor Mount Tai.", idiomatic: "In the second month, on jimao day, he favored Lu and advanced to Mount Tai." },
  { zh: "辛卯，晨，燎，祭天於泰山下南方，群神皆從，用樂如南郊。", literal: "On the day xinmao, at dawn, burned offerings, sacrificed to Heaven south of Mount Tai, all spirits following, music as at the southern suburban altar.", idiomatic: "On xinmao day, at dawn, he burned offerings and sacrificed to Heaven south of Mount Tai, all spirits following, with music as at the southern suburban altar." },
  { zh: "事畢，至食時，天子御輦登山，日中後，到山上，更衣。", literal: "When the rites were done, by mealtime the Son of Heaven mounted the palanquin up the mountain; after midday reached the summit and changed garments.", idiomatic: "When the rites were done, by mealtime the Son of Heaven mounted the palanquin up the mountain; after midday he reached the summit and changed garments." },
  { zh: "晡時，升壇北面，尚書令奉玉牒檢，天子以寸二分璽親封之，訖，太常命騶騎二千餘人發壇上方石，尚書令藏玉牒已，復石覆訖，尚書令以五寸印封石檢。", literal: "At the shen hour he ascended the altar facing north; Director of the Masters of Writing presented the jade covenant slip; the Son of Heaven with the one-cun two-fen seal personally sealed it; when done, Grand Director of Ceremonies ordered more than two thousand outrunners to open the altar's upper stones; Director of Writing stored the jade covenant, again covered with stone; Director of Writing sealed the stone slip with a five-cun seal.", idiomatic: "At the shen hour he ascended the altar facing north; the Director of the Masters of Writing presented the jade covenant slip; the Son of Heaven personally sealed it with the one-cun two-fen seal; when done, the Grand Director of Ceremonies ordered more than two thousand outrunners to open the altar's upper stones; the Director of Writing stored the jade covenant, covered it again with stone, and sealed the stone slip with a five-cun seal." },
  { zh: "事畢，天子再拜。", literal: "When done, the Son of Heaven bowed twice.", idiomatic: "When done, the Son of Heaven bowed twice." },
  { zh: "群臣稱萬歲，乃復道下。", literal: "The ministers cried ten thousand years—then by the return path descended.", idiomatic: "The ministers cried ten thousand years, then descended by the return path." },
  { zh: "夜半後，上乃到山下，百官明旦乃訖。", literal: "After midnight the emperor then reached below the mountain; the hundred officials only at clear dawn were finished.", idiomatic: "After midnight the emperor reached below the mountain; the hundred officials were finished only at clear dawn." },
  { zh: "甲午，禪祭地於梁陰，以高後配，山川群神從，如元始中北郊故事。", literal: "On the day jiawu, chan sacrifice to Earth at Liangyin, with Grand Empress Dowager Gao as consort, mountains and rivers and host of spirits following, as Yuanfeng northern suburban precedent.", idiomatic: "On jiawu day he performed the chan sacrifice to Earth at Liangyin, with Grand Empress Dowager Gao as consort, mountains and rivers and the host of spirits following, as in the Yuanfeng northern suburban precedent." },
  { zh: "三月，戊辰，司空張純薨。", literal: "In the third month, on the day wuchen, Minister of Works Zhang Chun died.", idiomatic: "In the third month, on wuchen day, Minister of Works Zhang Chun died." },
  { zh: "夏，四月，癸酉，車駕還宮；", literal: "In summer, the fourth month, on the day guiyou, the imperial carriage returned to the palace;", idiomatic: "In summer, in the fourth month, on guiyou day, the imperial carriage returned to the palace;" },
  { zh: "己卯，赦天下，改元。", literal: "On the day jimao, amnesty for all under heaven, changed reign title.", idiomatic: "On jimao day he granted amnesty to all under heaven and changed the reign title." },
  { zh: "上行幸長安；", literal: "The emperor went, favoring Chang'an;", idiomatic: "The emperor went to Chang'an;" },
  { zh: "五月，乙丑，還宮。", literal: "In the fifth month, on the day yichou, returned to the palace.", idiomatic: "In the fifth month, on yichou day, he returned to the palace." },
  { zh: "六月，辛卯，以太僕馮魴為司空。", literal: "In the sixth month, on the day xinmao, made Grand Superintendent Feng Fang Minister of Works.", idiomatic: "In the sixth month, on xinmao day, Grand Superintendent Feng Fang was made Minister of Works." },
  { zh: "乙未，司徒馮勤薨。", literal: "On the day yiwei, Minister of Education Feng Qin died.", idiomatic: "On yiwei day Minister of Education Feng Qin died." },
  { zh: "京師醴泉湧出，又有赤草生於水崖，郡國頻上甘露。", literal: "In the capital sweet springs bubbled forth; also red grass grew on water cliffs; commanderies and kingdoms repeatedly presented sweet dew.", idiomatic: "In the capital sweet springs bubbled forth; red grass also grew on water cliffs; commanderies and kingdoms repeatedly presented sweet dew." },
  { zh: "群臣奏言：「靈物仍降，宜令太史撰集，以傳來世。", literal: "The ministers submitted: \"Numinous things repeatedly descend—it is fitting to order the Grand Astrologer to compile and collect, to transmit to later generations.\"", idiomatic: "The ministers submitted, \"Numinous things repeatedly descend—it is fitting to order the Grand Astrologer to compile and collect them, to transmit to later generations.\"" },
  { zh: "」帝不納。", literal: "\" The emperor did not accept.", idiomatic: "\" The emperor did not accept." },
  { zh: "常自謙無德，每郡國所上，輒抑而不當，故史官罕得記焉。", literal: "He constantly modestly said he lacked virtue; whenever commanderies and kingdoms presented such things he always restrained and did not approve—therefore historians rarely could record them.", idiomatic: "He constantly modestly said he lacked virtue; whenever commanderies and kingdoms presented such things he always restrained and did not approve them—therefore historians rarely could record them." },
  { zh: "秋，郡國三蝗。", literal: "In autumn, three commanderies and kingdoms—locusts.", idiomatic: "In autumn, locusts struck three commanderies and kingdoms." },
  { zh: "冬，十月，辛未，以司隸校尉東萊李言斤為司徒。", literal: "In winter, the tenth month, on the day xinwei, made Director of the Masters of Writing Li Yanjin of Donglai Minister of Education.", idiomatic: "In winter, in the tenth month, on xinwei day, Director of the Masters of Writing Li Yanjin of Donglai was made Minister of Education." },
  { zh: "甲申，使司空告祠高廟，上薄太后尊號曰高皇后，配食地祇。", literal: "On the day jiashen, sent Minister of Works to announce sacrifice at the High Temple; elevated Empress Dowager Bo's honorific to Grand Empress Dowager Gao, consort to Earth Spirit.", idiomatic: "On jiashen day he sent the Minister of Works to announce sacrifice at the High Temple, elevated Empress Dowager Bo's honorific to Grand Empress Dowager Gao, and made her consort to the Earth Spirit." },
  { zh: "遷呂太后廟主於園，四時上祭。", literal: "Moved Empress Dowager Lü's temple tablet to the garden—four seasons she received sacrifice.", idiomatic: "He moved Empress Dowager Lü's temple tablet to the garden, where she received sacrifice in all four seasons." },
  { zh: "十一月，甲子晦，日有食之。", literal: "In the eleventh month, on the last day jiazi, there was an eclipse of the sun.", idiomatic: "In the eleventh month, on the last day of the month, jiazi day, there was a solar eclipse." },
  { zh: "是歲，起明堂、靈台、辟雍，宣佈圖讖於天下。", literal: "This year the Bright Hall, Spirit Terrace, and Imperial Academy were raised, and chart-prophecies were proclaimed throughout the realm.", idiomatic: "This year the Bright Hall, Spirit Terrace, and Imperial Academy were raised, and chart-prophecies were proclaimed throughout the realm." },
  { zh: "初，上以《赤伏符》即帝位，由是信用讖文，多以決定嫌疑。", literal: "At first the Emperor took the throne by the Chifu Talisman; from this he trusted prophecy texts and often used them to decide doubtful cases.", idiomatic: "At first the Emperor had taken the throne by the Chifu Talisman; from this he trusted prophecy texts and often used them to decide doubtful cases." },
  { zh: "給事中桓譚上疏諫曰：「凡人情忽於見事而貴於異聞。", literal: "Supervisor of the Palace Huan Tan submitted a memorial remonstrating, saying: \"As a rule human feelings neglect what is before one's eyes and prize strange reports.", idiomatic: "Supervisor of the Palace Huan Tan submitted a memorial remonstrating, saying, \"As a rule people neglect what is before their eyes and prize strange reports." },
  { zh: "觀先王之所記述，鹹以仁義正道為本，非有奇怪虛誕之事。", literal: "Observing what the former kings recorded, all took benevolence, righteousness, and the correct Way as their foundation—there were no strange, empty, or absurd matters.", idiomatic: "Observing what the former kings recorded, all took benevolence, righteousness, and the correct Way as their foundation—there were no strange, empty, or absurd matters." },
  { zh: "蓋天道性命，聖人所難言也，自子貢以下，不得而聞，況後世淺儒，能通之乎！", literal: "Heaven's Way, fate, and nature—the sages find them hard to speak of; from Zigong down one could not hear of them—how much less can shallow scholars of later ages master them!", idiomatic: "Heaven's Way, fate, and nature—the sages find them hard to speak of; from Zigong down one could not hear of them—how much less can shallow scholars of later ages master them!\"" },
  { zh: "今諸巧慧小才、伎數之人，增益圖書，矯稱讖記，以欺惑貪邪，詿誤人主，焉可不抑遠之哉！", literal: "Now the various clever petty talents and arts of technique add to charts and books, falsely style them prophecy records, to deceive and bewilder the greedy and wicked and mislead the ruler—how can they not be suppressed and kept at a distance!", idiomatic: "Now clever petty talents and masters of technique add to charts and books, falsely style them prophecy records, to deceive the greedy and wicked and mislead the ruler—how can they not be suppressed and kept at a distance!\"" },
  { zh: "臣譚伏聞陛下窮折方士黃白之術，甚為明矣；", literal: "Your servant Tan has heard that Your Majesty thoroughly refuted the alchemists' arts of yellow and white—this was very clear;", idiomatic: "I have heard that Your Majesty thoroughly refuted the alchemists' arts of transmuting metals—this was very clear;" },
  { zh: "而乃欲聽納讖記，又何誤也！", literal: "yet now you wish to listen to and accept prophecy records—what error is this!", idiomatic: "yet now you wish to listen to and accept prophecy records—what error is this!\"" },
  { zh: "其事雖有時合，譬猶卜數只偶之類。", literal: "Though such matters sometimes coincide, they are like divination numbers that happen to match by chance.", idiomatic: "Though such matters sometimes coincide, they are like divination numbers that happen to match by chance." },
  { zh: "陛下宜垂明聽，發聖意，屏君小之曲說，述《五經》之正義。", literal: "Your Majesty ought to extend enlightened hearing, release sagely intent, set aside petty twisted doctrines, and expound the correct meaning of the Five Classics.", idiomatic: "Your Majesty ought to extend enlightened hearing, release sagely intent, set aside petty twisted doctrines, and expound the correct meaning of the Five Classics.\"" },
  { zh: "」疏奏，帝不悅。", literal: "\" When the memorial was presented the Emperor was displeased.", idiomatic: "\" When the memorial was presented the Emperor was displeased." },
  { zh: "會議靈台所處，帝謂譚曰：「吾以讖決之，何如？", literal: "When they met to discuss the Spirit Terrace's location the Emperor said to Tan: \"I will decide it by prophecy—what do you think?", idiomatic: "When they met to discuss the Spirit Terrace's location the Emperor said to Tan, \"I will decide it by prophecy—what do you think?\"" },
  { zh: "」譚默然，良久曰：「臣不讀讖。", literal: "\" Tan was silent; after a long while he said: \"Your servant does not read prophecies.", idiomatic: "\" Tan was silent; after a long while he said, \"I do not read prophecies.\"" },
  { zh: "」帝問其故，譚復極言讖之非經。", literal: "\" The Emperor asked the reason; Tan again spoke to the utmost that prophecies are not canonical.", idiomatic: "\" The Emperor asked the reason; Tan again spoke at length that prophecies are not canonical." },
  { zh: "帝大怒曰：「桓譚非聖無法，將下，斬之！", literal: "The Emperor was greatly angered and said: \"Huan Tan rejects the sages and has no law—I shall have him taken down and beheaded!", idiomatic: "The Emperor was greatly angered and said, \"Huan Tan rejects the sages and has no law—I shall have him taken down and beheaded!\"" },
  { zh: "」譚叩頭流血，良久，乃得解。", literal: "\" Tan knocked his head until it bled; after a long while he was released.", idiomatic: "\" Tan knocked his head until it bled; after a long while he was released." },
  { zh: "出為六安郡丞，道病卒。", literal: "He was sent out as Assistant Administrator of Lu'an commandery and died of illness on the road.", idiomatic: "He was sent out as Assistant Administrator of Lu'an commandery and died of illness on the road." },
  { zh: "══范曄論曰：桓譚以不善讖流亡，鄭興以遜辭僅免；", literal: "══ Fan Ye's commentary says: Huan Tan, for disliking prophecies, was exiled; Zheng Xing, by evasive words, barely escaped;", idiomatic: "══ Fan Ye's commentary says: Huan Tan, for disliking prophecies, was exiled; Zheng Xing, by evasive words, barely escaped;" },
  { zh: "賈逵能附會文致，最差貴顯；", literal: "Jia Kui could attach and match literary flourishes and was by far the most honored and prominent;", idiomatic: "Jia Kui could attach and match literary flourishes and was by far the most honored and prominent;" },
  { zh: "世主以此論學，悲哉！", literal: "rulers of the age used this to judge learning—alas!", idiomatic: "rulers of the age used this to judge learning—alas!" },
  { zh: "逵，扶風人也。", literal: "Kui was a man of Fufeng.", idiomatic: "Kui was a man of Fufeng." },
  { zh: "南單于比死，弟左賢王莫立，為丘浮尤鞮單于。", literal: "The Southern Chanyu Bi died; his younger brother the Left Wise King Mo was established as Chanyu Qiufuyoudi.", idiomatic: "The Southern Chanyu Bi died; his younger brother the Left Wise King Mo was established as Chanyu Qiufuyoudi." },
  { zh: "帝遣使繼璽書拜授璽綬，賜以衣冠及繒彩，是後遂以為常。", literal: "The Emperor sent envoys with successive imperial-seal documents to invest him with seal and cord, granted robes and caps and silks, and thereafter this became regular practice.", idiomatic: "The Emperor sent envoys with successive imperial-seal documents to invest him with seal and cord, granted robes, caps, and silks, and thereafter this became regular practice." },
  { zh: "春，正月，辛未，初立北郊，祀后土。", literal: "In spring, the first month, on xinwei, the Northern Suburban Altar was first established and Queen Earth was sacrificed to.", idiomatic: "In spring, the first month, on xinwei, the Northern Suburban Altar was first established and Queen Earth was sacrificed to." },
  { zh: "二月，戊戌，帝崩於南宮前殿，年六十二。", literal: "In the second month, on wuxu, the Emperor died in the front hall of the Southern Palace, aged sixty-two.", idiomatic: "In the second month, on wuxu, the Emperor died in the front hall of the Southern Palace, aged sixty-two." },
  { zh: "帝每旦視朝，日昃乃罷，數引公卿、郎將講論經理，夜分乃寐。", literal: "Each morning the Emperor held court and only at sundown would dismiss; he repeatedly summoned Excellencies, ministers, and commandants of the palace to discuss governance and principles, and only at midnight would sleep.", idiomatic: "Each morning the Emperor held court and only at sundown would dismiss; he repeatedly summoned Excellencies, ministers, and commandants of the palace to discuss governance and principles, and only at midnight would sleep." },
  { zh: "皇太子見帝勤勞不怠，承間諫曰：「陛下有禹、湯之明，而失黃、老養性之福，願頤愛精神，優遊自寧。", literal: "The heir apparent, seeing the Emperor's diligence without slackening, took an opportunity to remonstrate: \"Your Majesty has the clarity of Yu and Tang yet loses the blessing of Yellow Emperor and Laozi's nurturing of nature—I wish you would cherish your spirit and ease yourself in leisure.", idiomatic: "The heir apparent, seeing the Emperor's diligence without slackening, took an opportunity to remonstrate, \"Your Majesty has the clarity of Yu and Tang yet loses the blessing of nurturing one's nature in the manner of the Yellow Emperor and Laozi—I wish you would cherish your spirit and ease yourself in leisure.\"" },
  { zh: "」帝曰：「我自樂此，不為疲也！", literal: "\" The Emperor said: \"I myself delight in this—it is not weariness!", idiomatic: "\" The Emperor said, \"I myself delight in this—it is not weariness!\"" },
  { zh: "」雖以征伐濟大業，及天下既定，乃退功臣而進文吏，明慎政體，總攬權綱，量時度力，舉無過事，故能恢復前烈，身致太平。", literal: "\" Though he used campaigns to complete the great enterprise, once the realm was settled he retired meritorious ministers and advanced civil officials, made the governmental body clear and careful, gathered all authority in his grasp, measured the times and gauged strength, and in action had no excess—therefore he could restore the former glory and personally attain great peace.", idiomatic: "\" Though he used campaigns to complete the great enterprise, once the realm was settled he retired meritorious ministers and advanced civil officials, made government clear and careful, gathered all authority in his grasp, measured times and strength, and in action had no excess—therefore he could restore the former glory and personally attain great peace." },
  { zh: "太尉趙熹典喪事。", literal: "Grand Commandant Zhao Xi directed the funeral affairs.", idiomatic: "Grand Commandant Zhao Xi directed the funeral affairs." },
  { zh: "時經王莽之亂，舊典不存，皇太子與諸王雜止同席，籓國官屬出入宮省，與百僚無別。", literal: "The realm had passed through Wang Mang's disorder; old regulations did not survive—the heir apparent and the various princes lodged mixed together on the same seats, and fief-state officials came and went within the palace precincts no differently from the hundred officials.", idiomatic: "The realm had passed through Wang Mang's disorder; old regulations did not survive—the heir apparent and the various princes lodged mixed together on the same seats, and fief-state officials came and went within the palace precincts no differently from the hundred officials." },
  { zh: "熹正色，橫劍殿階，扶下諸王以明尊卑；", literal: "Xi with stern countenance, sword across the hall steps, supported the princes down to make clear superior and inferior;", idiomatic: "Xi with stern countenance, sword across the hall steps, supported the princes down to make clear superior and inferior;" },
  { zh: "奏遣謁者將護官屬分止它縣，諸王並令就邸，唯得朝晡入臨；", literal: "memorialized to send Gentlemen-Usher Generals to escort officials to lodge separately in other counties, ordered all princes to their residences, and allowed them only to enter morning and evening to attend the bier;", idiomatic: "memorialized to send Gentlemen-Usher Generals to escort officials to lodge separately in other counties, ordered all princes to their residences, and allowed them only to enter morning and evening to attend the bier;" },
  { zh: "整禮儀，嚴門衛，內外肅然。", literal: "he set in order ritual and decorum, tightened gate guards, and within and without all was solemn.", idiomatic: "he set in order ritual and decorum, tightened gate guards, and within and without all was solemn." },
  { zh: "太子即皇帝位，尊皇后曰皇太后。", literal: "The heir apparent assumed the imperial throne and honored the empress as empress dowager.", idiomatic: "The heir apparent assumed the imperial throne and honored the empress as empress dowager." },
  { zh: "山陽王荊哭臨不哀，而作飛書，令蒼頭詐稱大鴻臚郭況書與東海王強，言其無罪被廢，及郭后黜辱，勸令東歸舉兵以取天下，且曰：「高祖起亭長，陛下興白水，何況於王，陛下長子、故副主哉！", literal: "Prince Jing of Shanyang did not mourn at the lying-in-state but wrote a flying letter, ordering a house servant to forge a letter in the name of Grand Herald Guo Kuang to Prince Qiang of Donghai, saying he had been deposed without crime and that Empress Guo had been disgraced and deposed, urging him to return east and raise troops to take the realm, and further: \"The High Emperor rose from a pavilion chief; Your Majesty arose at Baishui—how much more a prince, Your Majesty's eldest son and former heir!", idiomatic: "Prince Jing of Shanyang did not mourn at the lying-in-state but wrote a flying letter, ordering a house servant to forge a letter in the name of Grand Herald Guo Kuang to Prince Qiang of Donghai, saying he had been deposed without crime and that Empress Guo had been disgraced and deposed, urging him to return east and raise troops to take the realm, and further, \"The High Emperor rose from a pavilion chief; Your Majesty arose at Baishui—how much more a prince, Your Majesty's eldest son and former heir!\"" },
  { zh: "當為秋霜，無為檻羊。", literal: "You ought to be autumn frost—do not be a penned sheep.", idiomatic: "You ought to be autumn frost—do not be a penned sheep.\"" },
  { zh: "人主崩亡，閭閻之伍尚為盜賊，欲有所望，何況王邪！", literal: "When a ruler dies, even alleyway fellows still become bandits—if one wishes to have hope, how much more a prince!", idiomatic: "When a ruler dies, even alleyway fellows still become bandits—if one wishes to have hope, how much more a prince!\"" },
  { zh: "」強得書惶怖，即執其使，封書上之。", literal: "\" Qiang received the letter in fear and alarm, at once seized the messenger, sealed the letter, and presented it above.", idiomatic: "\" Qiang received the letter in fear and alarm, at once seized the messenger, sealed the letter, and presented it above." },
  { zh: "明帝以荊母弟，秘其事，遣荊出止河南宮。", literal: "Emperor Ming, because Jing was his younger brother by the same mother, kept the matter secret and sent Jing out to lodge at the Henan Palace.", idiomatic: "Emperor Ming, because Jing was his younger brother by the same mother, kept the matter secret and sent Jing out to lodge at the Henan Palace." },
  { zh: "三月，丁卯，葬光武皇帝於原陵。", literal: "In the third month, on dingmao, Emperor Guangwu was buried at Yuanling.", idiomatic: "In the third month, on dingmao, Emperor Guangwu was buried at Yuanling." },
  { zh: "夏，四月，丙辰，詔曰：「方今上無天子，下無方伯，若涉淵水而無舟楫。", literal: "In summer, the fourth month, on bingchen, an edict said: \"At present above there is no Son of Heaven, below no regional lords—as if crossing deep water without boat or oar.", idiomatic: "In summer, the fourth month, on bingchen, an edict said, \"At present above there is no Son of Heaven, below no regional lords—as if crossing deep water without boat or oar." },
  { zh: "夫萬乘至重而壯者慮輕，實賴有德左右小子。", literal: "The ten-thousand-chariot throne is supremely weighty yet the vigorous take it lightly—in truth one relies on virtuous elders to assist the young.", idiomatic: "The throne is supremely weighty yet the vigorous take it lightly—in truth one relies on virtuous elders to assist the young." },
  { zh: "高密侯禹，元功之首；", literal: "Marquis of Gaomi Yu was foremost among the founding merit;", idiomatic: "Marquis of Gaomi Yu was foremost among the founding merit;" },
  { zh: "東平王蒼，寬博有謀。", literal: "Prince of Dongping Cang was broad and generous and possessed strategy.", idiomatic: "Prince of Dongping Cang was broad and generous and possessed strategy." },
  { zh: "有以禹為太傅，蒼為驃騎將軍。", literal: "Yu was appointed Grand Tutor and Cang Flying-Cavalry General.", idiomatic: "Yu was appointed Grand Tutor and Cang Flying-Cavalry General." },
  { zh: "」蒼懇辭，帝不許。", literal: "\" Cang earnestly declined; the Emperor would not permit it.", idiomatic: "\" Cang earnestly declined; the Emperor would not permit it." },
  { zh: "又詔驃騎將軍置長史、掾史員四十人，位在三公上。", literal: "Another edict ordered the Flying-Cavalry General to have forty Chief Clerk and Clerk posts, rank above the Three Excellencies.", idiomatic: "Another edict ordered the Flying-Cavalry General to have forty Chief Clerk and Clerk posts, rank above the Three Excellencies." },
  { zh: "蒼嘗薦西曹掾齊國吳良，帝曰：「薦賢助國，宰相之職也。", literal: "Cang once recommended Western Bureau Clerk Wu Liang of Qi; the Emperor said: \"Recommending the worthy to aid the state is a chancellor's duty.", idiomatic: "Cang once recommended Western Bureau Clerk Wu Liang of Qi; the Emperor said, \"Recommending the worthy to aid the state is a chancellor's duty." },
  { zh: "蕭何舉韓信，設壇而拜，不復考試，今以良為議郎。", literal: "Xiao He raised Han Xin, set up an altar and invested him, and did not examine him again—now make Liang Gentleman Consultant.", idiomatic: "Xiao He raised Han Xin, set up an altar and invested him, and did not examine him again—now make Liang Gentleman Consultant.\"" },
  { zh: "初，燒當羌豪滇良擊破先零，奪居其地；", literal: "At first the Shaodang Qiang chieftain Dian Liang defeated and broke the Xianlian and seized their territory;", idiomatic: "At first the Shaodang Qiang chieftain Dian Liang defeated and broke the Xianlian and seized their territory;" },
  { zh: "滇良卒，子滇吾立，附落轉盛。", literal: "Dian Liang died; his son Dian Wu was established and the attached tribes grew ever stronger.", idiomatic: "Dian Liang died; his son Dian Wu was established and the attached tribes grew ever stronger." },
  { zh: "秋，滇吾與弟滇岸率眾寇隴西，敗太守劉盱於允街，於是守寨諸羌皆叛。", literal: "In autumn Dian Wu and his younger brother Dian An led the masses to raid Longxi and defeated Administrator Liu Xu at Yunjie; thereupon all the Qiang guarding stockades rebelled.", idiomatic: "In autumn Dian Wu and his younger brother Dian An led their forces to raid Longxi and defeated Administrator Liu Xu at Yunjie; thereupon all the Qiang guarding stockades rebelled." },
  { zh: "詔謁者張鴻領諸郡兵擊之，戰於允吾，鴻軍敗沒。", literal: "An edict ordered Gentleman-Usher Zhang Hong to lead the various commanderies' troops to strike them; they fought at Yunwu and Hong's army was defeated and destroyed.", idiomatic: "An edict ordered Gentleman-Usher Zhang Hong to lead the various commanderies' troops to strike them; they fought at Yunwu and Hong's army was defeated and destroyed." },
  { zh: "冬，十一月，復遣中郎將竇固監捕虜將軍馬武第二將軍、四萬人討之。", literal: "In winter, the eleventh month, Commandant of the Palace Dou Gu was again sent to supervise General Who Captures Barbarians Ma Wu the Second General and forty thousand men to campaign against them.", idiomatic: "In winter, the eleventh month, Commandant of the Palace Dou Gu was again sent to supervise General Who Captures Barbarians Ma Wu the Second General and forty thousand men to campaign against them." },
  { zh: "是歲，南單于莫死，弟汗立，為伊伐於慮鞮單于。", literal: "This year the Southern Chanyu Mo died; his younger brother Han was established as Chanyu Yifayulü.", idiomatic: "This year the Southern Chanyu Mo died; his younger brother Han was established as Chanyu Yifayulü." },
  { zh: "顯宗孝明皇帝上", literal: "Emperor Xiaoming, posthumous name Xiaozong, first part", idiomatic: "Emperor Xiaoming, posthumous name Xiaozong, first part" },
  { zh: "春，正月，帝率公卿已下朝於原陵，如元會儀。", literal: "In spring, the first month, the Emperor led the Excellencies and below to attend court at Yuanling, as in the New Year's assembly rites.", idiomatic: "In spring, the first month, the Emperor led the Excellencies and below to attend court at Yuanling, as in the New Year's assembly rites." },
  { zh: "乘輿拜神坐，退，坐東廂；", literal: "The imperial carriage bowed before the spirit seat, withdrew, and sat in the east wing;", idiomatic: "The imperial carriage bowed before the spirit seat, withdrew, and sat in the east wing;" },
  { zh: "侍衛官皆在神坐後，太官上食，太常奏樂；", literal: "guard officers were all behind the spirit seat; the Grand Provisioner presented food and the Grand Master of Ceremonies played music;", idiomatic: "guard officers were all behind the spirit seat; the Grand Provisioner presented food and the Grand Master of Ceremonies played music;" },
  { zh: "郡國上計吏以次前，當神軒佔其郡谷價及民所疾苦。", literal: "the commanderies' and states' reporting clerks advanced in turn before the spirit window and stated their commandery's grain prices and the people's afflictions.", idiomatic: "the commanderies' and states' reporting clerks advanced in turn before the spirit window and stated their commandery's grain prices and the people's afflictions." },
  { zh: "是後遂以為常。", literal: "After this it became regular practice.", idiomatic: "After this it became regular practice." },
  { zh: "夏，五月，高密元侯鄧禹薨。", literal: "In summer, the fifth month, Marquis Yuan of Gaomi Deng Yu died.", idiomatic: "In summer, the fifth month, Marquis Yuan of Gaomi Deng Yu died." },
  { zh: "東海恭王強病，上遣使者太醫乘驛視疾，駱驛不絕。", literal: "Prince Gong of Donghai Qiang fell ill; the Emperor sent envoys and the imperial physician by post-horses to visit his illness, relays unceasing.", idiomatic: "Prince Gong of Donghai Qiang fell ill; the Emperor sent envoys and the imperial physician by post-horses to visit his illness, relays unceasing." },
  { zh: "詔沛王輔、濟南王康、淮陽王延詣魯省疾。", literal: "An edict ordered Princes Fu of Pei, Kang of Jinan, and Yan of Huaiyang to go to Lu to inquire after his illness.", idiomatic: "An edict ordered Princes Fu of Pei, Kang of Jinan, and Yan of Huaiyang to go to Lu to inquire after his illness." },
  { zh: "戊寅，強薨，臨終，上疏謝恩，言：「身既夭命，孤弱復為皇太后、陛下憂慮，誠悲誠慚！", literal: "On wuyin Qiang died; at life's end he submitted a memorial thanking grace, saying: \"My person has met early death; weak and alone I again cause the empress dowager and Your Majesty worry—truly grieved and truly ashamed!", idiomatic: "On wuyin Qiang died; at life's end he submitted a memorial thanking grace, saying, \"My person has met early death; weak and alone I again cause the empress dowager and Your Majesty worry—truly grieved and truly ashamed!\"" },
  { zh: "息政，小人也，猥當襲臣後，必非所以全利之也，願還東海郡。", literal: "Xi Zheng, a petty man, unworthily is to succeed your servant's line—it surely is not what will wholly benefit him; I wish the Donghai commandery returned.", idiomatic: "Xi Zheng, a petty man, unworthily is to succeed my line—it surely is not what will wholly benefit him; I wish the Donghai commandery returned." },
  { zh: "今天下新罹大憂，惟陛下加供養皇太后，數進御餐。", literal: "Now the realm has newly suffered great grief—only wish Your Majesty increase nourishment of the empress dowager and frequently send imperial meals.", idiomatic: "Now the realm has newly suffered great grief—only wish Your Majesty increase nourishment of the empress dowager and frequently send imperial meals." },
  { zh: "臣強困劣，言不能盡意，願並謝諸王，不意永不復相見也！", literal: "Your servant Qiang is feeble and inferior; words cannot fully express my intent—I wish also to thank the various princes; I did not expect never to meet again!", idiomatic: "I am feeble and inferior; words cannot fully express my intent—I wish also to thank the various princes; I did not expect never to meet again!\"" },
  { zh: "」帝覽書悲慟，從太后出幸津門亭發哀，使大司空持節護喪事，贈送以殊禮，詔楚王英、趙王栩、北海王興及京師親戚皆會葬。", literal: "\" The Emperor read the memorial in grief and anguish, accompanied the empress dowager out to Jinmen Pavilion to begin mourning, sent the Grand Minister of Works with staff of authority to oversee funeral affairs, granted send-off with extraordinary rites, and ordered Princes Ying of Chu, Xu of Zhao, Xing of Beihai, and kin in the capital all to assemble for the burial.", idiomatic: "\" The Emperor read the memorial in grief and anguish, accompanied the empress dowager out to Jinmen Pavilion to begin mourning, sent the Grand Minister of Works with staff of authority to oversee funeral affairs, granted send-off with extraordinary rites, and ordered Princes Ying of Chu, Xu of Zhao, Xing of Beihai, and kin in the capital all to assemble for the burial." },
  { zh: "帝追惟強深執謙儉，不欲厚葬以違其意，於是特詔：「遺送之物，務從約省，衣足斂形，茅車瓦器，物減於制，以彰王卓爾獨行之志。", literal: "The Emperor recalled Qiang's deep adherence to humility and frugality and did not wish a lavish burial against his intent; thereupon a special edict: \"Objects sent with the dead must follow economy and restraint—clothes enough to cover the form, thatched cart and earthen vessels, goods reduced below regulation, to display the prince's outstanding solitary conduct.", idiomatic: "The Emperor recalled Qiang's deep adherence to humility and frugality and did not wish a lavish burial against his intent; thereupon a special edict, \"Objects sent with the dead must follow economy and restraint—clothes enough to cover the form, thatched cart and earthen vessels, goods reduced below regulation, to display the prince's outstanding solitary conduct.\"" },
  { zh: "」將作大匠留起陵廟。", literal: "\" The Master of Works was retained to raise the tomb shrine.", idiomatic: "\" The Master of Works was retained to raise the tomb shrine." },
  { zh: "秋，七月，馬武等擊燒當羌，大破之，餘皆降散。", literal: "In autumn, the seventh month, Ma Wu and others struck the Shaodang Qiang and routed them greatly; the remainder all surrendered and dispersed.", idiomatic: "In autumn, the seventh month, Ma Wu and others struck the Shaodang Qiang and routed them greatly; the remainder all surrendered and dispersed." },
  { zh: "山陽王荊私迎能為星者，與謀議，冀天下有變。", literal: "Prince Jing of Shanyang privately welcomed one skilled in stars, consulted and plotted with him, hoping the realm would have upheaval.", idiomatic: "Prince Jing of Shanyang privately welcomed one skilled in stars, consulted and plotted with him, hoping the realm would have upheaval." },
  { zh: "帝聞之，徙封荊廣陵王，遣之國。", literal: "The Emperor heard of it, transferred Jing's fief to Prince of Guangling, and sent him to his state.", idiomatic: "The Emperor heard of it, transferred Jing's fief to Prince of Guangling, and sent him to his state." },
  { zh: "遼東太守祭肜使偏何討赤山烏桓，大破之，斬其魁帥。", literal: "Administrator of Liaodong Ji Yong sent Pian He to campaign against the Chishan Wuhuan, routed them greatly, and beheaded their chief leader.", idiomatic: "Administrator of Liaodong Ji Yong sent Pian He to campaign against the Chishan Wuhuan, routed them greatly, and beheaded their chief leader." },
  { zh: "塞外震讋，西自武威，東盡玄菟，皆來內附，野無風塵，乃悉罷緣邊屯兵。", literal: "Beyond the passes all trembled in fear; from Wuwei in the west to Xuantu in the east all came to submit within; the wilds had no wind and dust, and thereupon all frontier garrison troops were dismissed.", idiomatic: "Beyond the passes all trembled in fear; from Wuwei in the west to Xuantu in the east all came to submit within; the wilds had no wind and dust, and thereupon all frontier garrison troops were dismissed." },
  { zh: "東平王蒼以為中興三十餘年，四方無虞，宜修禮樂，乃與公卿共議定南北郊冠冕、車服制度及光武廟登歌、八俏舞數，上之。", literal: "Prince of Dongping Cang held that after more than thirty years of restoration the four quarters were without worry and ritual and music ought to be restored; he thereupon with the Excellencies and ministers jointly discussed and fixed the southern and northern suburban sacrifices' caps and robes, chariot and garment systems, and Guangwu's temple ascending hymns and eight rows of dancers, and presented them above.", idiomatic: "Prince of Dongping Cang held that after more than thirty years of restoration the four quarters were without worry and ritual and music ought to be restored; he thereupon with the Excellencies and ministers jointly discussed and fixed the southern and northern suburban sacrifices' caps and robes, chariot and garment systems, and Guangwu's temple ascending hymns and eight rows of dancers, and presented them above." },
  { zh: "好畦愍侯耿弇薨。", literal: "Marquis Min of Haoqi Geng Yan died.", idiomatic: "Marquis Min of Haoqi Geng Yan died." },
  { zh: "春，正月，辛未，宗祀光琥皇帝於明堂，帝及公卿列侯，始服冠冕、玉珮以行事。", literal: "In spring, the first month, on xinwei, ancestral sacrifice was made to Emperor Guangwu at the Bright Hall; the Emperor and Excellencies and ranked marquises for the first time wore caps and robes and jade pendants to perform the rites.", idiomatic: "In spring, the first month, on xinwei, ancestral sacrifice was made to Emperor Guangwu at the Bright Hall; the Emperor and Excellencies and ranked marquises for the first time wore caps and robes and jade pendants to perform the rites." },
  { zh: "禮畢，登靈台，望雲物。", literal: "When the rites were complete they ascended the Spirit Terrace and observed cloud omens.", idiomatic: "When the rites were complete they ascended the Spirit Terrace and observed cloud omens." },
  { zh: "赦天下。", literal: "An amnesty was proclaimed for the realm.", idiomatic: "An amnesty was proclaimed for the realm." },
  { zh: "三月，臨辟雍，初行大射禮。", literal: "In the third month he attended the Imperial Academy and for the first time performed the great archery rite.", idiomatic: "In the third month he attended the Imperial Academy and for the first time performed the great archery rite." },
  { zh: "冬，十月，壬子，上幸辟雍，初行養老禮；", literal: "In winter, the tenth month, on renzi, the Emperor visited the Imperial Academy and for the first time performed the elderly-nurturing rite;", idiomatic: "In winter, the tenth month, on renzi, the Emperor visited the Imperial Academy and for the first time performed the elderly-nurturing rite;" },
  { zh: "以李躬為三老，桓榮為五更。", literal: "Li Gong was made Elder of the Three and Huan Rong Elder of the Five.", idiomatic: "Li Gong was made Elder of the Three and Huan Rong Elder of the Five." },
  { zh: "三老服都紵大袍，冠進賢，扶玉杖；", literal: "The Elder of the Three wore a great robe of patterned silk, the Forward Worthy cap, and leaned on a jade staff;", idiomatic: "The Elder of the Three wore a great robe of patterned silk, the Forward Worthy cap, and leaned on a jade staff;" },
  { zh: "五更亦如之，不杖。", literal: "the Elder of the Five was likewise but without staff.", idiomatic: "the Elder of the Five was likewise but without staff." },
  { zh: "乘輿到壁雍禮殿，御坐東廂，遣使者安車迎三老、五更於太學講堂，天子迎於門屏，交禮；", literal: "The imperial carriage arrived at the Biyong ritual hall; the Emperor sat in the east wing, sent envoys with the comfort carriage to welcome the Elder of the Three and Elder of the Five from the Imperial Academy lecture hall; the Son of Heaven welcomed them at the gate screen and exchanged ritual;", idiomatic: "The imperial carriage arrived at the Biyong ritual hall; the Emperor sat in the east wing, sent envoys with the comfort carriage to welcome the Elder of the Three and Elder of the Five from the Imperial Academy lecture hall; the Son of Heaven welcomed them at the gate screen and exchanged ritual;" },
  { zh: "道自阼階，三老升自賓階；", literal: "the path went from the host's steps; the Elder of the Three ascended by the guest steps;", idiomatic: "the path went from the host's steps; the Elder of the Three ascended by the guest steps;" },
  { zh: "至階，天子揖如禮。", literal: "at the steps the Son of Heaven bowed according to ritual.", idiomatic: "at the steps the Son of Heaven bowed according to ritual." },
  { zh: "三老升，東面，三公設幾，九卿正履，天子親袒割牲，執醬而饋，執爵而酳，祝鯁在前，祝饐在後。", literal: "The Elder of the Three ascended, faced east; the Three Excellencies set the armrest, the Nine Ministers straightened their shoes; the Son of Heaven personally bared shoulder, cut the victim, held sauce and fed, held the cup and made them rinse, the prayer against choking before and the prayer for satiety after.", idiomatic: "The Elder of the Three ascended, faced east; the Three Excellencies set the armrest, the Nine Ministers straightened their shoes; the Son of Heaven personally bared shoulder, cut the victim, held sauce and fed, held the cup and made them rinse, the prayer against choking before and the prayer for satiety after." },
  { zh: "五更南面，三公進供，禮亦如之。", literal: "The Elder of the Five faced south; the Three Excellencies advanced provisions—the rites were likewise.", idiomatic: "The Elder of the Five faced south; the Three Excellencies advanced provisions—the rites were likewise." },
  { zh: "禮畢，引桓榮及弟子升堂，上自為下說，諸儒執經問難於前，冠帶搢紳之人圜橋門而觀聽者，蓋億萬計。", literal: "When the rites were complete Huan Rong and his disciples were led up the hall; the Emperor himself came down to lecture; the various scholars held the classics and posed difficulties before him; gentlemen with caps and sashes and girdled officials around the bridge gate who watched and listened numbered on the order of hundreds of millions.", idiomatic: "When the rites were complete Huan Rong and his disciples were led up the hall; the Emperor himself came down to lecture; the various scholars held the classics and posed difficulties before him; gentlemen with caps and sashes around the bridge gate who watched and listened numbered on the order of hundreds of millions." },
  { zh: "於是下詔賜榮爵關內侯；", literal: "Thereupon an edict was issued granting Rong rank as Marquis within the Passes;", idiomatic: "Thereupon an edict was issued granting Rong rank as Marquis within the Passes;" },
  { zh: "三老、五更皆以二千石祿養終厥身。", literal: "the Elder of the Three and Elder of the Five were all given two-thousand-bushel salary to nourish them to life's end.", idiomatic: "the Elder of the Three and Elder of the Five were all given two-thousand-bushel salary to nourish them to life's end." },
  { zh: "賜天下三老酒，人一石，肉四十斤。", literal: "Wine was granted to elders of the three throughout the realm, one stone per person and forty jin of meat.", idiomatic: "Wine was granted to elders of the three throughout the realm, one stone per person and forty jin of meat." },
  { zh: "上自為太子，受《尚書》於桓榮，及即帝位，猶尊榮以師禮。", literal: "From the time he was heir apparent the Emperor received the Documents from Huan Rong; when he assumed the throne he still honored Rong with teacher's rites.", idiomatic: "From the time he was heir apparent the Emperor received the Documents from Huan Rong; when he assumed the throne he still honored Rong with teacher's rites." },
  { zh: "嘗幸太常府，令榮坐東面，設幾杖，會百官及榮門生數百人，上親自執業；", literal: "He once visited the Grand Master of Ceremonies' office, ordered Rong to sit facing east, set armrest and staff, assembled the hundred officials and several hundred of Rong's students; the Emperor personally held the mat;", idiomatic: "He once visited the Grand Master of Ceremonies' office, ordered Rong to sit facing east, set armrest and staff, assembled the hundred officials and several hundred of Rong's students; the Emperor personally held the mat;" },
  { zh: "諸生或避位發難，上謙曰：「太師在是。", literal: "the students sometimes left their places to pose difficulties; the Emperor modestly said: \"The Grand Preceptor is here.", idiomatic: "the students sometimes left their places to pose difficulties; the Emperor modestly said, \"The Grand Preceptor is here.\"" },
  { zh: "」既罷，悉以太官供具賜太常家。", literal: "\" When it was finished he entirely granted the Grand Provisioner's supplies to the Grand Master of Ceremonies' household.", idiomatic: "\" When it was finished he entirely granted the Grand Provisioner's supplies to the Grand Master of Ceremonies' household." },
  { zh: "榮每疾病，帝輒遣使者存問，太官、太醫相望於道。", literal: "Whenever Rong fell ill, the Emperor would send envoys to inquire after him; the Imperial Cuisine and Imperial Physicians lined the road.", idiomatic: "Whenever Huan Rong fell ill, the Emperor would send envoys to inquire after him; Imperial Cuisine and Imperial Physicians lined the road." },
  { zh: "及篤，上疏謝恩，讓還爵士。", literal: "When his illness grew grave, he submitted a memorial thanking for grace and yielding back his rank and fief.", idiomatic: "When his illness grew grave, he submitted a memorial thanking the Emperor for his grace and offering to return his rank and fief." },
  { zh: "帝幸其家問起居，入街，下車，擁經而前，撫榮垂涕，賜以床茵、帷帳、刀劍、衣被，良久乃去。", literal: "The Emperor visited his home to inquire after his health; entering the lane he dismounted, embraced the classics and advanced, stroked Rong and shed tears, bestowed bed mats, curtains, swords, and clothing, and only after long departed.", idiomatic: "The Emperor visited his home to inquire after his health; entering the lane he dismounted from his carriage, embraced the classics and advanced, stroked Rong and wept, bestowed bed mats, curtains, swords, and clothing, and only after a long while departed." },
  { zh: "自是諸侯、將軍、大夫問疾者，不敢復乘車到門，皆拜床下。", literal: "From this time feudatory lords, generals, and grandees who came to inquire after his illness did not dare again ride carriages to the gate—all bowed below the couch.", idiomatic: "From this time feudatory lords, generals, and grandees who came to inquire after his illness did not dare ride carriages to the gate—all bowed below his couch." },
  { zh: "榮卒，帝親自變服臨喪送葬，賜塚塋於首山之陽。", literal: "When Rong died the Emperor personally changed garb to attend the mourning and escort the burial, granting a tomb mound on the sunny slope of Mount Shou.", idiomatic: "When Rong died the Emperor personally changed garb to attend the funeral and escort the burial, granting a tomb mound on the sunny slope of Mount Shou." },
  { zh: "子郁當嗣，讓其兄子泛；", literal: "His son Yu was to inherit; he yielded to his elder brother's son Fan;", idiomatic: "His son Yu was to inherit; he yielded to his elder brother's son Fan;" },
  { zh: "帝不許，郁乃受封，而悉以租入與之。", literal: "the Emperor would not allow it; Yu then accepted the enfeoffment but gave all the rental income to him.", idiomatic: "the Emperor would not allow it; Yu then accepted the enfeoffment but gave all the rental income to Fan." },
  { zh: "帝以郁為侍中。", literal: "The Emperor made Yu Palace Attendant.", idiomatic: "The Emperor made Yu Palace Attendant." },
  { zh: "上以中山王焉，郭太后少子，太后尤愛之，故獨留京師，至是始與諸王俱就國，賜以虎賁、官騎，恩寵尤厚，獨得往來京師。", literal: "The Emperor because Prince of Zhongshan Yan was Empress Dowager Guo's youngest son and the Empress Dowager especially loved him had kept him alone in the capital; only now did he with the other kings go to their states; he was granted Huben and official escort, favor especially thick—alone permitted to travel back and forth to the capital.", idiomatic: "Because Prince of Zhongshan Liu Yan was Empress Dowager Guo's youngest son and she especially loved him, the Emperor had kept him alone in the capital; only now did he go to his state with the other kings. He was granted Huben guards and an official escort, with favor especially thick—alone permitted to travel back and forth to the capital." },
  { zh: "帝禮待陰、郭，每事必均，數受賞賜，恩寵俱渥。", literal: "The Emperor treated Yin and Guo with ritual courtesy; in every matter he must balance them; they repeatedly received rewards and favors, favor and grace both generous.", idiomatic: "The Emperor treated the Yin and Guo clans with ritual courtesy, balancing them in every matter; they repeatedly received rewards, and favor and grace were alike generous." },
  { zh: "甲子，上行幸長安。", literal: "On day jiazi the Emperor traveled in person to Chang'an.", idiomatic: "On jiazi day the Emperor traveled in person to Chang'an." },
  { zh: "十一月，甲申，遣使者以中牢祠蕭何、霍光。", literal: "In the eleventh month, on day jiashen, he sent envoys with medium victim sacrifice to worship Xiao He and Huo Guang.", idiomatic: "In the eleventh month, on jiashen day, he sent envoys with medium victim sacrifice to worship Xiao He and Huo Guang." },
  { zh: "帝過，式其墓。", literal: "The Emperor passed by and posthumously bowed toward their tombs.", idiomatic: "As he passed by, the Emperor bowed toward their tombs." },
  { zh: "進幸河東；", literal: "He proceeded in person to Hedong;", idiomatic: "He proceeded in person to Hedong;" },
  { zh: "癸卯，還宮。", literal: "On day guimao he returned to the palace.", idiomatic: "On guimao day he returned to the palace." },
  { zh: "十二月，護羌校尉竇林坐欺罔及臧罪，下獄死。", literal: "In the twelfth month Protector of the Qiang Dou Lin was convicted of deception and embezzlement, imprisoned, and died.", idiomatic: "In the twelfth month Protector of the Qiang Dou Lin was convicted of deception and embezzlement, imprisoned, and died." },
  { zh: "林者，融之從兄子也。", literal: "Lin was Rong's cousin's son.", idiomatic: "Lin was Dou Rong's cousin's son." },
  { zh: "於是竇氏一公、兩侯、三公主、四二千石相與並時，自祖及孫，官府邸第相望京邑，於親戚功臣中莫與為比。", literal: "Thus the Dou clan had one duke, two marquises, three princesses, and four holders of two-thousand-shi salary all flourishing together; from grandfather to grandson official residences and mansion compounds lined the capital—among kin and meritorious ministers none could compare.", idiomatic: "Thus the Dou clan had one duke, two marquises, three princesses, and four officials at two-thousand-shi salary all flourishing at once; from grandfather to grandson official residences and mansions lined the capital—among kin and meritorious ministers none could compare." },
  { zh: "及林誅，帝數干詔切責融，融惶恐乞骸骨，詔令歸第養病。", literal: "When Lin was executed the Emperor repeatedly sent edicts sternly reproaching Rong; Rong in fear and trepidation begged to resign his bones; an edict ordered him to return to his residence and nurse his illness.", idiomatic: "When Lin was executed the Emperor repeatedly sent edicts sternly reproaching Dou Rong; Rong in fear begged to resign; an edict ordered him to return to his residence and nurse his illness." },
  { zh: "是歲，初迎氣於五郊。", literal: "This year for the first time they welcomed qi at the five suburban altars.", idiomatic: "This year for the first time qi was welcomed at the five suburban altars." },
  { zh: "新陽侯陰就子豐尚酈邑公主。", literal: "Feng, son of Marquis of Xinyang Yin Jiu, married the Princess of Liyi.", idiomatic: "Feng, son of Marquis of Xinyang Yin Jiu, married the Princess of Liyi." },
  { zh: "公主驕妒，豐殺之，被誅，父母皆自殺。", literal: "The princess was proud and jealous; Feng killed her and was executed; his parents both committed suicide.", idiomatic: "The princess was proud and jealous; Feng killed her and was executed; his parents both committed suicide." },
  { zh: "南單于汗死，單于比之子適立，為□盆僮屍逐侯鞮單于。", literal: "Southern Chanyu Han died; Shiy, son of Chanyu Bi's son, was established as □pen Tongshi Zhuhou Di Chanyu.", idiomatic: "Southern Chanyu Han died; Shiy, son of Chanyu Bi's son, was established as □ Xi Li Shizhu Houdi Chanyu." },
  { zh: "春，二月，甲寅，太尉趙、司徒李言斤免。", literal: "In spring, the second month, on day jiayin, Grand Commandant Zhao and Minister of Education Li Yanjin were dismissed.", idiomatic: "In spring, the second month, on jiayin day, Grand Commandant Zhao Xian and Minister of Education Li Jing were dismissed." },
  { zh: "丙辰，以左馮翊郭丹為司徒。", literal: "On day bingchen the Left Colonel of the Metropolitan Area Guo Dan was made Minister of Education.", idiomatic: "On bingchen day the Left Colonel of the Metropolitan Area Guo Dan was made Minister of Education." },
  { zh: "己未，以南陽太守虞延為太尉。", literal: "On day jiwei the Administrator of Nanyang Yu Yan was made Grand Commandant.", idiomatic: "On jiwei day the Administrator of Nanyang Yu Yan was made Grand Commandant." },
  { zh: "甲子，立貴人馬氏為皇后，皇子炟為太子。", literal: "On day jiazi Worthy Lady Ma was established as Empress and the prince Da as Crown Prince.", idiomatic: "On jiazi day Worthy Lady Ma was established as Empress and the prince Da as Crown Prince." },
  { zh: "後，援之女也，光武時，以選入太子宮，能奉承陰後，傍接同列，禮則修備，上下安之，遂見寵異；", literal: "The Empress was Yuan's daughter; in Guangwu's time she was selected into the Crown Prince's palace, able to serve Empress Yin, connect with peers at her side, ritual and deportment complete and prepared, above and below were at peace through her, and she came to be favored exceptionally;", idiomatic: "The Empress was Ma Yuan's daughter; in Emperor Guangwu's time she was selected into the Crown Prince's palace, able to serve Empress Yin, connect with her peers, her ritual and deportment complete and correct, putting those above and below at ease, and she came to be exceptionally favored;" },
  { zh: "及帝即位，為貴人。", literal: "when the Emperor took the throne she became Worthy Lady.", idiomatic: "when the Emperor took the throne she became Worthy Lady." },
  { zh: "時後前母姊女賈氏亦以選入，生皇子炟。", literal: "At that time Jia, niece of the former empress's elder sister, was also selected in and bore the prince Da.", idiomatic: "At that time Jia, niece of the former empress's elder sister, was also selected in and bore the prince Da." },
  { zh: "帝以後無子，命養之，謂曰：「人未必當自生子，但患愛養不至耳！", literal: "The Emperor because the Empress had no son ordered her to rear him, saying: \"A person need not necessarily bear her own child—only fear that loving care and nurturing do not reach the mark!", idiomatic: "Because the Empress had no son, the Emperor ordered her to rear him, saying, \"A person need not necessarily bear her own child—only fear that love and care in raising him do not suffice!\"" },
  { zh: "」後於是盡心撫育，勞悴過於所生。", literal: "\" The Empress thereupon gave her whole heart to raising him, weariness and hardship exceeding those for a child of her own womb.", idiomatic: "The Empress thereupon gave her whole heart to raising him, with weariness and hardship exceeding those for a child of her own womb." },
  { zh: "太子亦孝性淳篤，母子慈愛，始終無纖介之間。", literal: "The Crown Prince's filial nature was pure and thick; mother and son loving and kind—from beginning to end no trace of division between them.", idiomatic: "The Crown Prince's filial nature was pure and sincere; mother and son were loving and kind—from beginning to end without the slightest rift between them." },
  { zh: "後常以皇嗣未廣，薦達左右，若恐不及。", literal: "The Empress often because the imperial heirs were not yet broad recommended and advanced those about her, as if afraid it would not be enough.", idiomatic: "The Empress often because the imperial heirs were not yet numerous recommended and advanced those about her, as if afraid she could not do enough." },
  { zh: "後宮有進見者，每加慰納；", literal: "When palace women came forward to be received, she always added comfort and acceptance;", idiomatic: "When palace women came forward to be received, she always comforted and accepted them;" },
  { zh: "若數所寵引，輒加隆遇。", literal: "if any were several times favored and summoned, she would yet add preferment and encounter.", idiomatic: "if any were several times favored and summoned, she would yet treat them with added honor." },
  { zh: "及有司奏立長秋宮，帝未有所言，皇太后曰：「馬貴人德冠後宮，即其人也。", literal: "When the authorities memorialized to establish the Changqiu Palace, the Emperor had said nothing; the Empress Dowager said: \"Worthy Lady Ma's virtue tops the rear palace—let her be the one.", idiomatic: "When the authorities memorialized to establish the Changqiu Palace, the Emperor had said nothing; the Empress Dowager said, \"Worthy Lady Ma's virtue tops the rear palace—let her be the one.\"" },
  { zh: "」後既正位宮闈，愈自謙肅，好讀書。", literal: "\" After the Empress took her proper place within the palace gates she became all the more modest and reverent; she loved reading books.", idiomatic: "After the Empress took her proper place within the palace gates she became all the more modest and reverent and loved reading books." },
  { zh: "常衣大練，裙不加緣；", literal: "She always wore large plain hemp; her skirt had no border trimming;", idiomatic: "She always wore coarse plain hemp; her skirt had no border trimming;" },
  { zh: "朔望諸姬主朝請，望見後袍衣疏粗，以為綺縠，就視，乃笑。", literal: "on the first and fifteenth of the month the various consorts and princesses came to court audience; seeing the Empress's robe and garments coarse and thin they thought them silk and brocade—approaching to look they laughed.", idiomatic: "on the first and fifteenth of the month the various consorts and princesses came to court audience; seeing the Empress's robe and garments coarse and thin they thought them silk and brocade—approaching to look, they laughed." },
  { zh: "後曰：「此繒特宜染色，故用之耳。", literal: "The Empress said: \"This silk is especially suitable for dyeing—that is why I use it.", idiomatic: "The Empress said, \"This silk is especially suitable for dyeing—that is why I use it.\"" },
  { zh: "」群臣奏事有難平者，帝數以試後，後輒分解趣理，各得其情，然未嘗以傢俬干政事。", literal: "\" When the ministers submitted matters hard to settle the Emperor often used them to test the Empress; she would always resolve and explain to the principle; each obtained its circumstances—yet she never used private family interest to interfere in government affairs.", idiomatic: "When the ministers submitted matters hard to settle the Emperor often used them to test the Empress; she would always resolve them according to principle, each obtaining its proper circumstances—yet she never used private family interest to interfere in government affairs." },
  { zh: "帝由是寵敬，始終無衰焉。", literal: "The Emperor thereby favored and respected her; from beginning to end there was no decline.", idiomatic: "The Emperor thereby favored and respected her; from beginning to end his regard never waned." },
  { zh: "帝思中興功臣，乃圖畫二十八將於南宮雲台，以鄧禹為首，次馬成、吳漢、王梁、賈復、陳俊、耿弇、杜茂、寇恂、傅俊、岑彭、堅金覃、馮異、王霸、朱祜、任光、祭遵、李忠、景丹、萬修、蓋延、邳肜、銚期、劉植、耿純、臧宮、馬武、劉隆，又益以王常、李通、竇融、卓茂，合三十二人。", literal: "The Emperor thought of the Restoration meritorious ministers and therefore painted portraits of the twenty-eight generals at the Cloud Terrace of the Southern Palace, with Deng Yu first, next Ma Cheng, Wu Han, Wang Liang, Jia Fu, Chen Jun, Geng Yin, Du Mao, Kou Xun, Fu Jun, Cen Peng, Jian Jin Tan, Feng Yi, Wang Ba, Zhu Hu, Ren Guang, Ji Zun, Li Zhong, Jing Dan, Wan Xiu, Gai Yan, Pi Yin, Yao Qi, Liu Zhi, Geng Chun, Zang Gong, Ma Wu, Liu Long, and further added Wang Chang, Li Tong, Dou Rong, and Zhuo Mao—thirty-two in all.", idiomatic: "The Emperor thought of the Restoration meritorious ministers and therefore painted portraits of the twenty-eight generals at the Cloud Terrace of the Southern Palace, with Deng Yu first, followed by Ma Cheng, Wu Han, Wang Liang, Jia Fu, Chen Jun, Geng Yin, Du Mao, Kou Xun, Fu Jun, Cen Peng, Jian Tan, Feng Yi, Wang Ba, Zhu Hu, Ren Guang, Ji Zun, Li Zhong, Jing Dan, Wan Xiu, Gai Yan, Pi Yin, Yao Qi, Liu Zhi, Geng Chun, Zang Gong, Ma Wu, and Liu Long, with Wang Chang, Li Tong, Dou Rong, and Zhuo Mao added—thirty-two in all." },
  { zh: "馬援以椒房之親，獨不與焉。", literal: "Ma Yuan because of empress kinship was alone not included.", idiomatic: "Ma Yuan, because of empress kinship, was alone not included." },
  { zh: "夏，四月，辛酉，封皇子建為千乘王，羨為廣平王。", literal: "In summer, the fourth month, on day xinyou, the prince Jian was enfeoffed as King of Qiansheng and Xian as King of Guangping.", idiomatic: "In summer, the fourth month, on xinyou day, the prince Jian was enfeoffed as King of Qiansheng and Xian as King of Guangping." },
  { zh: "六月，丁卯，有星孛於天船北。", literal: "In the sixth month, on day dingmao, a comet appeared north of the Celestial Boat.", idiomatic: "In the sixth month, on dingmao day, a comet appeared north of the Celestial Boat." },
  { zh: "帝大起北宮。", literal: "The Emperor greatly raised the North Palace.", idiomatic: "The Emperor undertook a major expansion of the North Palace." },
  { zh: "時天旱，尚書僕射會稽鐘離意詣闕，免冠，上疏曰：「昔成湯遭旱，以六事自責曰：『政不節邪？", literal: "At the time there was drought; Vice Director of the Masters of Writing Zhongli Yi of Kuaiji came to the palace gate, removed his cap, and submitted a memorial, saying: \"In the past when Cheng Tang encountered drought he took six matters to blame himself, saying: 'Is government not restrained?", idiomatic: "At the time there was drought; Vice Director of the Masters of Writing Zhongli Yi of Kuaiji came to the palace gate, removed his cap, and submitted a memorial, saying, \"In the past when Cheng Tang encountered drought he blamed himself in six matters, saying, 'Is government not restrained?\"" },
  { zh: "使民疾邪？", literal: "Does one cause the people illness?", idiomatic: "Does one cause the people illness?\"" },
  { zh: "宮室榮邪？", literal: "Are palaces and chambers glorious?", idiomatic: "Are palaces and chambers too splendid?\"" },
  { zh: "女謁盛邪？", literal: "Are women's petitions excessive?", idiomatic: "Are women's petitions excessive?\"" },
  { zh: "苞苴行邪？", literal: "Do wrapped gifts go about?", idiomatic: "Do bribes go about?\"" },
  { zh: "讒夫昌邪？", literal: "Do slanderers flourish?", idiomatic: "Do slanderers flourish?'\"" },
  { zh: "』竊見北宮大作，民失農時；", literal: "' I have seen the North Palace built on a great scale and the people lose the season for farming;", idiomatic: "I have seen the North Palace built on a great scale and the people lose the season for farming;" },
  { zh: "自古非苦宮室小狹，但患民不安寧，宜且罷止，以應天心。", literal: "from ancient times the hardship was not that palaces were small and narrow, but that one feared the people were not at peace—it is fitting for now to cease and stop, to respond to Heaven's heart.", idiomatic: "from ancient times the hardship was not that palaces were small and narrow, but that the people were not at peace—it is fitting to cease for now and respond to Heaven's heart." },
  { zh: "」帝策詔報曰：「湯引六事，咎在一人，其冠、履，勿謝！", literal: "\" The Emperor's written edict in reply said: \"Tang cited six matters—the blame lies in one man; as for your cap and shoes, do not apologize!", idiomatic: "\" The Emperor's written reply said, \"Tang cited six matters—the blame lies in one man; as for your cap and shoes, do not apologize!\"" },
  { zh: "」又敕大匠止作諸宮，減省不急。", literal: "\" He also ordered the Grand Artisan to stop work on the various palaces and reduce what was not urgent.", idiomatic: "He also ordered the Grand Artisan to stop work on the various palaces and reduce what was not urgent." },
  { zh: "詔因謝公卿百僚，遂慶時澍雨。", literal: "An edict thereupon apologized to the excellencies, ministers, and hundred officials, and then timely rain was celebrated.", idiomatic: "An edict thereupon apologized to the excellencies, ministers, and hundred officials, and timely rain then fell." },
  { zh: "意薦全椒長劉平，詔征拜議郎。", literal: "Yi recommended Magistrate of Quanjiao Liu Ping; an edict summoned and appointed him Master of the Forest.", idiomatic: "Yi recommended Magistrate of Quanjiao Liu Ping; an edict summoned and appointed him Master of the Forest." },
  { zh: "平在全椒，政有恩惠，民或增貲就賦，或減年從役。", literal: "Ping in Quanjiao had government with kindness and grace; the people sometimes increased their goods to meet the tax levy, sometimes reduced years to follow corvée.", idiomatic: "Ping in Quanjiao governed with kindness and grace; the people sometimes increased their payments to meet the tax levy, sometimes reduced years of service to follow corvée." },
  { zh: "剌史、太守行部，獄無系囚，人自以得所，不知所問，唯班詔書而去。", literal: "When the Inspector and Administrator made their circuit of the commandery, the prisons had no prisoners held in bonds; the people each felt they had their place and did not know what to ask—he only distributed the edict documents and departed.", idiomatic: "When the Inspector and Administrator made their circuit of the commandery, the prisons had no prisoners in bonds; the people each felt they had their place and did not know what to ask—he only distributed the edict documents and departed." },
  { zh: "帝性褊察，好以耳目隱發為明，公卿大臣數被詆毀，近臣尚書以下至見提曳。", literal: "The Emperor was by nature narrow and scrutinizing, fond of taking what ears and eyes secretly uncovered as proof of perspicacity; excellencies and ministers were repeatedly slandered and destroyed; close ministers from Masters of Writing down were even seen dragged about.", idiomatic: "The Emperor was by nature narrow and scrutinizing, fond of treating what spies secretly uncovered as proof of perspicacity; excellencies and ministers were repeatedly slandered; close ministers from Masters of Writing down were even seen dragged about." },
  { zh: "常以事怒郎藥崧，以杖撞之；", literal: "He often in anger at Attendant Yao Song struck him with a staff;", idiomatic: "He often in anger at Attendant Yao Song struck him with a staff;" },
  { zh: "崧走入床下，帝怒甚，疾言曰：「郎出！", literal: "Song ran under the couch; the Emperor was greatly angered and spoke sharply: \"Attendant, come out!", idiomatic: "Song ran under the couch; the Emperor was greatly angered and spoke sharply, \"Attendant, come out!\"" },
  { zh: "」崧乃曰：「天子穆穆，諸侯皇皇，未聞人君，自起撞郎。", literal: "\" Song then said: \"The Son of Heaven is solemn and still, the feudatory lords majestic and bright—I have not heard of a ruler rising himself to strike an Attendant.", idiomatic: "Song then said, \"The Son of Heaven is solemn and still, the feudatory lords majestic and bright—I have not heard of a ruler rising himself to strike an Attendant.\"" },
  { zh: "」帝乃赦之。", literal: "\" The Emperor thereupon pardoned him.", idiomatic: "The Emperor thereupon pardoned him." },
  { zh: "是時朝廷莫不悚心栗，爭為嚴切以避誅責，唯鍾離意獨敢諫爭，數封還詔書，臣下過失，輒救解之。", literal: "At this time at court none failed to be fearful at heart and trembling, each striving to be stern and harsh to avoid blame and punishment—only Zhongli Yi alone dared remonstrate and dispute, several times sealing and returning edict documents; when subordinates had faults he would rescue and release them.", idiomatic: "At this time at court none failed to be fearful at heart and trembling, each striving to be stern and harsh to avoid blame and punishment—only Zhongli Yi alone dared remonstrate, several times sealing and returning edict documents; when subordinates had faults he would rescue and release them." },
  { zh: "會連有變異，上疏曰：「陛下敬畏鬼神，憂恤黎元，而天氣未和，寒暑違節者，咎在群臣不能宣化治職，而以苛刻為俗，百官無相親之心，吏民無雍雍之志，至於感逆和氣，以致天災。", literal: "Just then there were successive anomalies; he submitted a memorial, saying: \"Your Majesty reveres and fears ghosts and spirits and is anxious and pitying toward the black-haired people, yet the weather is not harmonious and cold and heat violate their seasons—the blame lies in the ministers being unable to proclaim transformation and govern their duties, but taking harshness as custom; the hundred officials have no hearts of mutual kinship; clerks and people have no will of harmonious ease—reaching the point of moving against harmonious qi and thereby bringing on Heaven's calamities.", idiomatic: "Just then there were successive anomalies; he submitted a memorial, saying, \"Your Majesty reveres and fears ghosts and spirits and is anxious and pitying toward the people, yet the weather is not harmonious and cold and heat violate their seasons—the blame lies in the ministers being unable to proclaim transformation and govern their duties, but taking harshness as custom; the hundred officials have no hearts of mutual kinship; clerks and people have no will of harmonious ease—reaching the point of moving against harmonious qi and thereby bringing on Heaven's calamities.\"" },
  { zh: "百姓可以德勝，難以力服，《鹿鳴》之詩必言宴樂者，以人神之心洽，然後天氣和也。", literal: "The hundred people can be overcome by virtue, hard to overcome by force; the Ode of the Deer Cry must speak of feasting and music because when human and spirit hearts are in accord, then the weather is harmonious.", idiomatic: "The people can be won by virtue, not easily subdued by force; the Ode of the Deer Cry must speak of feasting and music because when human and spirit hearts are in accord, then the weather is harmonious." },
  { zh: "願陛下垂聖德，緩刑罰，順時氣以調陰陽。", literal: "I wish Your Majesty to let sagely virtue descend, ease punishments, and follow the season's qi to harmonize yin and yang.", idiomatic: "I wish Your Majesty to let sagely virtue descend, ease punishments, and follow the season's qi to harmonize yin and yang." },
  { zh: "」帝雖不能用，然知其至誠，終愛厚之。", literal: "\" Though the Emperor could not employ it, yet knowing his utmost sincerity he to the end loved and favored him thickly.", idiomatic: "Though the Emperor could not employ his advice, yet knowing his utmost sincerity he to the end loved and favored him." },
  { zh: "秋，八月，戊辰，詔改太樂官曰太予，用讖文也。", literal: "In autumn, the eighth month, on day wuchen, an edict changed the office of Grand Musician to Grand Nurture, following prophecy texts.", idiomatic: "In autumn, the eighth month, on wuchen day, an edict changed the office of Grand Musician to Grand Nurture, following prophecy texts." },
  { zh: "壬申晦，日有食之。", literal: "On the last day of month renshen there was a solar eclipse.", idiomatic: "On the last day of renshen month there was a solar eclipse." },
  { zh: "詔曰：「昔楚莊無災，以致戒懼，魯哀禍大，天不降譴。", literal: "An edict said: \"In the past King Zhuang of Chu had no calamity yet thereby arrived at caution and fear; Duke Ai of Lu's calamity was great yet Heaven sent down no reprimand.", idiomatic: "An edict said, \"In the past King Zhuang of Chu had no calamity yet thereby arrived at caution and fear; Duke Ai of Lu's calamity was great yet Heaven sent down no reprimand.\"" },
  { zh: "今之動變，倘尚可救，有司勉思厥職，以匡無德。", literal: "Today's movements and changes—perhaps they can still be saved; the authorities should strive to think on their duties to rectify lack of virtue.", idiomatic: "Today's movements and changes—perhaps they can still be remedied; the authorities should strive to think on their duties to rectify lack of virtue." },
  { zh: "冬，十月，甲子，車駕從皇太后幸章陵。", literal: "In winter, the tenth month, on day jiazi, the imperial carriage followed the Empress Dowager in visiting Zhangling.", idiomatic: "In winter, the tenth month, on jiazi day, the imperial carriage followed the Empress Dowager in visiting Zhangling." },
  { zh: "荊州剌史郭賀，官有殊政，上賜以三公之服，黼黻，冕旒；", literal: "Inspector of Jingzhou Guo He had government with exceptional administration; the Emperor bestowed on him the garb of the Three Excellencies, fu-fu, and miǎn liú;", idiomatic: "Inspector of Jingzhou Guo He had government with exceptional administration; the Emperor bestowed on him the garb of the Three Excellencies, fu-fu, and miǎn liú;" },
  { zh: "敕行部去襜帷，使百姓見其容服，以章有德，戊辰，還自章陵。", literal: "he ordered that on his circuit of the commandery he remove the carriage curtains so the people could see his bearing and garb to display his virtue; on day wuchen he returned from Zhangling.", idiomatic: "he ordered that on his circuit of the commandery he remove the carriage curtains so the people could see his bearing and garb to display his virtue; on wuchen day he returned from Zhangling." },
  { zh: "是歲，京師及郡國七大水。", literal: "This year the capital and commanderies and kingdoms suffered seven great floods.", idiomatic: "This year the capital and commanderies and kingdoms suffered seven great floods." },
  { zh: "莎車王賢以兵威逼奪於窴、大宛、媯塞王國，使其將守之。", literal: "King Xian of Shache by military awesomeness compelled and seized the kingdoms of Yutian, Dayuan, and Guisai, making his generals guard them.", idiomatic: "King Xian of Shache by military force compelled and seized the kingdoms of Yutian, Dayuan, and Guisai, making his generals guard them." },
  { zh: "於窴人殺其將君德，立大人休莫霸為王。", literal: "The people of Yutian killed his general Junde and established the elder Xiumoba as king.", idiomatic: "The people of Yutian killed his general Junde and established the elder Xiumoba as king." },
  { zh: "賢率諸國兵數萬擊之，大為休莫霸所敗，脫身走還。", literal: "Xian led the troops of the various states, several tens of thousands, to strike them, was greatly defeated by Xiumoba, and escaped with his body and fled back.", idiomatic: "Xian led the troops of the various states, several tens of thousands, to strike them, was greatly defeated by Xiumoba, and fled back with his life." },
  { zh: "休莫霸進圍莎車，中流矢死，於窴人復立其兄子廣德為王，廣德使其弟仁攻賢。", literal: "Xiumoba advanced to besiege Shache and died from a stray arrow; the people of Yutian again established his elder brother's son Guangde as king; Guangde sent his younger brother Ren to attack Xian.", idiomatic: "Xiumoba advanced to besiege Shache and died from a stray arrow; the people of Yutian again established his elder brother's son Guangde as king; Guangde sent his younger brother Ren to attack Xian." },
  { zh: "廣德父先拘在莎車，賢乃歸其父，以女妻之，與之和親。", literal: "Guangde's father had earlier been detained in Shache; Xian thereupon returned his father, gave him his daughter in marriage, and made peace by marriage alliance.", idiomatic: "Guangde's father had earlier been detained in Shache; Xian thereupon returned his father, gave him his daughter in marriage, and made peace by marriage alliance." },
  { zh: "category:資治通鑑", literal: "—", idiomatic: "—" }
];
